struct Count { word: Str, n: Int }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("text.txt")?.to_str();
  let mut counts: Map<Str, Int> = Map::new();
  let mut cur = "";
  for c in text.chars() {
    let letter = (c >= "a" && c <= "z") || (c >= "A" && c <= "Z");
    if letter {
      cur = cur + c.to_lowercase();
    } else if cur != "" {
      counts.insert(cur, counts.get(cur).unwrap_or(0) + 1);
      cur = "";
    }
  }
  if cur != "" {
    counts.insert(cur, counts.get(cur).unwrap_or(0) + 1);
  }
  let mut rows: List<Count> = [];
  for w in counts.keys() {
    rows.push(Count { word: w, n: counts.get(w).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.word < b.word));
  let top = rows.slice(0, rows.len().min(5));
  Ok(top.map(|r| r.word + " " + r.n.to_str()).join("\n"))
}

struct Row { region: Str, qty: Int, rev: Int }

fn money(cents: Int) -> Str {
  let neg = cents < 0;
  let a = if neg { 0 - cents } else { cents };
  let c = a % 100;
  (if neg { "-" } else { "" }) + (a / 100).to_str() + "." + (if c < 10 { "0" } else { "" }) + c.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let lines = text.lines();
  let mut qtys: Map<Str, Int> = Map::new();
  let mut revs: Map<Str, Int> = Map::new();
  let mut skipped = 0;
  for i in 0..lines.len() {
    if i == 0 { continue; }
    let line = lines[i];
    if line.trim() == "" { continue; }
    let f = line.split(",");
    if f.len() != 5 { skipped += 1; continue; }
    let Some(q) = f[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = f[4].trim().parse_int() else { skipped += 1; continue; };
    let region = f[1].trim();
    qtys.insert(region, qtys.get(region).unwrap_or(0) + q);
    revs.insert(region, revs.get(region).unwrap_or(0) + q * u);
  }
  let mut rows: List<Row> = [];
  for r in qtys.keys() {
    rows.push(Row { region: r, qty: qtys.get(r).unwrap_or(0), rev: revs.get(r).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.rev > b.rev || (a.rev == b.rev && a.region < b.region));
  let mut out: List<Str> = rows.map(|r| r.region + " " + r.qty.to_str() + " " + money(r.rev));
  out.push("skipped " + skipped.to_str());
  Ok(out.join("\n"))
}

struct Entry { ip: Str, path: Str, status: Int, size: Int }
struct ErrRow { ip: Str, n: Int }

fn parse(line: Str) -> Option<Entry> {
  let parts = line.split("\"");
  if parts.len() != 3 { return None; }
  let ip = parts[0].trim().split(" ")[0];
  if ip == "" { return None; }
  let req = parts[1].split(" ");
  if req.len() != 3 { return None; }
  let path = req[1].split("?")[0];
  let rest = parts[2].trim().split(" ");
  if rest.len() != 2 { return None; }
  let status = rest[0].parse_int()?;
  let size = if rest[1] == "-" { 0 } else { rest[1].parse_int()? };
  Some(Entry { ip: ip, path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    total += e.size;
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    if e.status >= 500 && e.status < 600 {
      errs.insert(e.ip, errs.get(e.ip).unwrap_or(0) + 1);
    }
  }
  let mut out: List<Str> = [];
  for s in statuses.keys() {
    out.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }
  out.push("bytes " + total.to_str());
  let mut best = "";
  let mut best_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > best_n { best = p; best_n = n; }
  }
  if best_n > 0 {
    out.push("top " + best + " " + best_n.to_str());
  }
  let mut rows: List<ErrRow> = [];
  for ip in errs.keys() {
    rows.push(ErrRow { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for r in rows {
    out.push("errors " + r.ip + " " + r.n.to_str());
  }
  Ok(out.join("\n"))
}

fn total(order: Json) -> Int {
  let mut t = 0;
  for item in order.get("items").and_then(|v| v.as_list()).unwrap_or([]) {
    let qty = item.get("qty").and_then(|v| v.as_int()).unwrap_or(0);
    let price = item.get("price_cents").and_then(|v| v.as_int()).unwrap_or(0);
    t += qty * price;
  }
  t
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("orders.json")?.to_str();
  let Ok(doc) = text.parse_json() else { return Ok("bad json"); };
  let mut counts: Map<Str, Int> = Map::new();
  let mut sums: Map<Str, Int> = Map::new();
  let mut refunded_n = 0;
  let mut refunded_total = 0;
  let mut pending_n = 0;
  for order in doc.as_list().unwrap_or([]) {
    let status = order.get("status").and_then(|v| v.as_str()).unwrap_or("");
    let t = total(order);
    if status == "paid" {
      let c = order.get("customer").and_then(|v| v.as_str()).unwrap_or("");
      counts.insert(c, counts.get(c).unwrap_or(0) + 1);
      sums.insert(c, sums.get(c).unwrap_or(0) + t);
    } else if status == "refunded" {
      refunded_n += 1;
      refunded_total += t;
    } else if status == "pending" {
      pending_n += 1;
    }
  }
  let mut lines: List<Str> = [];
  for c in counts.keys() {
    lines.push(c + " " + counts.get(c).unwrap_or(0).to_str() + " " + sums.get(c).unwrap_or(0).to_str());
  }
  lines.push("refunded " + refunded_n.to_str() + " " + refunded_total.to_str());
  lines.push("pending " + pending_n.to_str());
  Ok(lines.join("\n"))
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for line in text.lines() {
    let s = line.trim().to_lowercase();
    if s == "" { continue; }
    let parts = s.split("@");
    if parts.len() != 2 { invalid += 1; continue; }
    let mut local = parts[0];
    let domain = parts[1];
    if local == "" || !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") {
      invalid += 1;
      continue;
    }
    if domain == "gmail.com" {
      if let Some(i) = local.find("+") {
        local = local.slice(0, i);
      }
      local = local.replace(".", "");
    }
    seen.insert(local + "@" + domain, true);
  }
  let mut keys = seen.keys();
  keys.sort();
  let mut out = "";
  for k in keys {
    out = out + k + "\n";
  }
  Ok(out + "invalid " + invalid.to_str())
}

fn to_roman(n: Int) -> Str {
  if n < 1 || n > 3999 { return ""; }
  let vals: List<Int> = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms: List<Str> = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut rest = n;
  let mut out = "";
  for i in 0..vals.len() {
    while rest >= vals[i] {
      out = out + syms[i];
      rest -= vals[i];
    }
  }
  out
}

fn val(c: Str) -> Int {
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn from_roman(s: Str) -> Option<Int> {
  let cs = s.chars();
  let n = cs.len();
  let mut total = 0;
  for i in 0..n {
    let v = val(cs[i]);
    if v == 0 { return None; }
    if i + 1 < n && v < val(cs[i + 1]) {
      total -= v;
    } else {
      total += v;
    }
  }
  if total < 1 || total > 3999 { return None; }
  if to_roman(total) == s { Some(total) } else { None }
}

fn convert(line: Str) -> Str {
  let n = if line.starts_with("+") { None } else { line.parse_int() };
  match n {
    Some(k) => {
      let r = to_roman(k);
      if r == "" { "invalid" } else { r }
    },
    None => match from_roman(line) {
      Some(k) => k.to_str(),
      None => "invalid",
    },
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("numbers.txt")?.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line == "" { continue; }
    out.push(line + " = " + convert(line));
  }
  Ok(out.join("\n"))
}

fn check(line: Str) -> Str {
  let cs = line.chars();
  let mut stack: List<Str> = [];
  for i in 0..cs.len() {
    let c = cs[i];
    if c == "(" {
      stack.push(")");
    } else if c == "[" {
      stack.push("]");
    } else if c == "{" {
      stack.push("}");
    } else if c == ")" || c == "]" || c == "}" {
      let Some(x) = stack.pop() else {
        return "col " + (i + 1).to_str() + ": unexpected " + c;
      };
      if x != c {
        return "col " + (i + 1).to_str() + ": expected " + x + ", found " + c;
      }
    }
  }
  if stack.len() == 0 {
    "ok"
  } else {
    "unclosed " + stack[stack.len() - 1]
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("snippets.txt")?.to_str();
  let out = text.lines().map(|l| check(l));
  Ok(out.join("\n"))
}

fn pct(t: List<Int>, p: Int) -> Int {
  let n = t.len();
  let idx = (p * n + 99) / 100;
  t[idx - 1]
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut groups: Map<Str, List<Int>> = Map::new();
  for line in text.lines() {
    let f = line.split(" ");
    if f.len() != 3 { continue; }
    let Some(ms) = f[2].parse_int() else { continue; };
    let key = f[0] + " " + f[1];
    let mut cur: List<Int> = groups.get(key).unwrap_or([]);
    cur.push(ms);
    groups.insert(key, cur);
  }
  let mut out: List<Str> = [];
  for key in groups.keys() {
    let mut t: List<Int> = groups.get(key).unwrap_or([]);
    t.sort();
    let n = t.len();
    out.push(key + " count=" + n.to_str() + " p50=" + pct(t, 50).to_str() + " p95=" + pct(t, 95).to_str() + " max=" + t[n - 1].to_str());
  }
  Ok(out.join("\n"))
}

struct Edge { to: Str, w: Int }
struct Trip { a: Str, b: Str }

fn add_edge(adj: Map<Str, List<Edge>>, a: Str, b: Str, w: Int) -> Map<Str, List<Edge>> {
  let mut m = adj;
  let mut l: List<Edge> = m.get(a).unwrap_or([]);
  l.push(Edge { to: b, w: w });
  m.insert(a, l);
  m
}

fn dists(adj: Map<Str, List<Edge>>, src: Str) -> Map<Str, Int> {
  let mut dist: Map<Str, Int> = Map::new();
  let mut done: Map<Str, Bool> = Map::new();
  dist.insert(src, 0);
  loop {
    let mut best = "";
    let mut bd = -1;
    for k in dist.keys() {
      if done.get(k).is_some() { continue; }
      let d = dist.get(k).unwrap_or(0);
      if bd < 0 || d < bd { bd = d; best = k; }
    }
    if bd < 0 { break; }
    done.insert(best, true);
    let edges: List<Edge> = adj.get(best).unwrap_or([]);
    for e in edges {
      let nd = bd + e.w;
      let c = dist.get(e.to).unwrap_or(-1);
      if c < 0 || nd < c { dist.insert(e.to, nd); }
    }
  }
  dist
}

fn route(adj: Map<Str, List<Edge>>, x: Str, y: Str) -> Str {
  if x == y { return x + " 0"; }
  let dist = dists(adj, y);
  let Some(total) = dist.get(x) else { return x + " " + y + " unreachable"; };
  let mut path = x;
  let mut cur = x;
  while cur != y {
    let du = dist.get(cur).unwrap_or(0);
    let mut next = "";
    let mut found = false;
    let edges: List<Edge> = adj.get(cur).unwrap_or([]);
    for e in edges {
      let dv = dist.get(e.to).unwrap_or(-1);
      if dv >= 0 && e.w + dv == du && (!found || e.to < next) {
        next = e.to;
        found = true;
      }
    }
    path += " -> " + next;
    cur = next;
  }
  path + " " + total.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut adj: Map<Str, List<Edge>> = Map::new();
  let mut trips: List<Trip> = [];
  for line in text.lines() {
    let t = line.trim();
    if t == "" || t.starts_with("#") { continue; }
    let f = t.split(" ").filter(|s| s != "");
    if f.len() == 4 && f[0] == "road" {
      let Some(w) = f[3].parse_int() else { continue; };
      adj = add_edge(adj, f[1], f[2], w);
      adj = add_edge(adj, f[2], f[1], w);
    } else if f.len() == 3 && f[0] == "trip" {
      trips.push(Trip { a: f[1], b: f[2] });
    }
  }
  let mut out: List<Str> = [];
  for t in trips {
    out.push(route(adj, t.a, t.b));
  }
  Ok(out.join("\n"))
}

struct Entry { path: Str, line: Str }

fn merge(base: Json, over: Json) -> Json {
  let Some(om) = over.as_map() else { return over; };
  let mut res: Map<Str, Json> = Map::new();
  if let Some(m) = base.as_map() { res = m; }
  for k in om.keys() {
    let v = om.get(k).unwrap_or(Json::Null);
    if v == Json::Null {
      res.remove(k);
      continue;
    }
    let b = res.get(k).unwrap_or(Json::Null);
    res.insert(k, merge(b, v));
  }
  Json::Obj(res)
}

fn flatten(j: Json, path: Str, acc: List<Entry>) -> List<Entry> {
  let mut out = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(Entry { path: path, line: path + "={}" });
      } else {
        for k in m.keys() {
          let p = if path == "" { k } else { path + "." + k };
          out = flatten(m.get(k).unwrap_or(Json::Null), p, out);
        }
      }
    },
    Json::Arr(xs) => {
      if xs.len() == 0 {
        out.push(Entry { path: path, line: path + "=[]" });
      } else {
        for i in 0..xs.len() {
          let p = if path == "" { i.to_str() } else { path + "." + i.to_str() };
          out = flatten(xs[i], p, out);
        }
      }
    },
    _ => {
      out.push(Entry { path: path, line: path + "=" + j.to_json() });
    },
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let a = input.read("base.json")?.to_str();
  let b = input.read("override.json")?.to_str();
  let Ok(base) = a.parse_json() else { return Ok("bad json"); };
  let Ok(over) = b.parse_json() else { return Ok("bad json"); };
  let merged = merge(base, over);
  let mut rows: List<Entry> = [];
  rows = flatten(merged, "", rows);
  rows.sort_by_key(|e| e.path);
  Ok(rows.map(|e| e.line).join("\n"))
}

fn body(xs: List<Str>) -> Str {
  if xs.len() == 0 { "" } else { xs.join("\n") + "\n" }
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut errs: List<Str> = [];
  let mut warns: List<Str> = [];
  let mut infos: List<Str> = [];
  let mut other = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let f = line.split(" ");
    if f.len() < 3 {
      other += 1;
      continue;
    }
    match f[1].to_uppercase() {
      "ERROR" => { errs.push(line); },
      "WARN" | "WARNING" => { warns.push(line); },
      "INFO" => { infos.push(line); },
      _ => { other += 1; },
    }
  }
  out.write("error.log", body(errs).to_bytes())?;
  out.write("warn.log", body(warns).to_bytes())?;
  out.write("info.log", body(infos).to_bytes())?;
  Ok("error " + errs.len().to_str() + "\nwarn " + warns.len().to_str() + "\ninfo " + infos.len().to_str() + "\nother " + other.to_str())
}

struct Row { path: Str, bytes: Int, lines: Int }

fn walk(d: Dir, dir: Str, rows: List<Row>) -> Result<List<Row>, IoErr> {
  let mut acc = rows;
  for name in d.list(dir)? {
    let is_dir = name.ends_with("/");
    let base = name.strip_suffix("/").unwrap_or(name);
    let p = if dir == "" { base } else { dir + "/" + base };
    if is_dir {
      acc = walk(d, p, acc)?;
    } else {
      let data = d.read(p)?;
      let mut nl = 0;
      let mut last = 0;
      for b in data {
        if b == 10 { nl += 1; }
        last = b;
      }
      let n = data.len();
      let lines = if n > 0 && last != 10 { nl + 1 } else { nl };
      acc.push(Row { path: p, bytes: n, lines: lines });
    }
  }
  Ok(acc)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let empty: List<Row> = [];
  let mut rows = walk(input, "", empty)?;
  rows.sort_by(|a, b| a.path < b.path);
  let mut csv = "path,bytes,lines\n";
  let mut total = 0;
  for r in rows {
    csv += r.path + "," + r.bytes.to_str() + "," + r.lines.to_str() + "\n";
    total += r.bytes;
  }
  out.write("index.csv", csv.to_bytes())?;
  Ok("files " + rows.len().to_str() + " bytes " + total.to_str())
}

fn split_csv(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if inq {
      if c == "\"" {
        if i + 1 < cs.len() && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i += 1;
        } else {
          inq = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "\"" {
        inq = true;
      } else if c == "," {
        fields.push(cur);
        cur = "";
      } else {
        cur = cur + c;
      }
    }
    i += 1;
  }
  fields.push(cur);
  fields
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut items: List<Json> = [];
  let mut skipped = 0;
  let mut header_seen = false;
  for raw in text.lines() {
    let line = raw.strip_suffix("\r").unwrap_or(raw);
    if line.trim() == "" { continue; }
    if !header_seen {
      header_seen = true;
      continue;
    }
    let f = split_csv(line);
    if f.len() != 5 {
      skipped += 1;
      continue;
    }
    let Some(id) = f[0].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let a = f[3].trim().to_lowercase();
    let active = a == "yes" || a == "true" || a == "1";
    let tags = f[4].split(";").map(|t| t.trim()).filter(|t| t != "").map(|t| Json::Str(t));
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(id));
    m.insert("name", Json::Str(f[1]));
    m.insert("email", Json::Str(f[2]));
    m.insert("active", Json::Bool(active));
    m.insert("tags", Json::Arr(tags));
    items.push(Json::Obj(m));
  }
  out.write("users.json", Json::Arr(items).to_json().to_bytes())?;
  Ok("rows " + items.len().to_str() + " skipped " + skipped.to_str())
}

fn normalize(orig: Str) -> Str {
  let lower = orig.to_lowercase();
  let mut name = "";
  let mut last_dash = false;
  for c in lower.chars() {
    let ok = c.len() == 1 && ((c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == ".");
    if ok {
      name += c;
      last_dash = false;
    } else if !last_dash {
      name += "-";
      last_dash = true;
    }
  }
  while name.starts_with("-") {
    name = name.slice(1, name.len());
  }
  while name.ends_with("-") {
    name = name.slice(0, name.len() - 1);
  }
  name
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut taken: Map<Str, Bool> = Map::new();
  let mut lines: List<Str> = [];
  for orig in names {
    let new_name = normalize(orig);
    if new_name == "" || taken.get(new_name).is_some() {
      lines.push(orig + " skipped");
      continue;
    }
    taken.insert(new_name, true);
    let data = input.read(orig)?;
    out.create(new_name, data)?;
    lines.push(orig + " -> " + new_name);
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  if name.len() != 13 || !name.starts_with("part-") || !name.ends_with(".txt") {
    return false;
  }
  for c in name.slice(5, 9).chars() {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut all: List<Int> = [];
  let mut parts = 0;
  let mut corrupt = 0;
  for name in input.list("")? {
    if !is_part(name) { continue; }
    parts += 1;
    let text = input.read(name)?.to_str();
    let mut vals: List<Int> = [];
    let mut bad = false;
    for line in text.lines() {
      let t = line.trim();
      if t == "" { continue; }
      let Some(n) = t.parse_int() else { bad = true; break; };
      vals.push(n);
    }
    if bad {
      corrupt += 1;
    } else {
      for v in vals { all.push(v); }
    }
  }
  all.sort();
  let mut body = "";
  let mut count = 0;
  let mut last = 0;
  for v in all {
    if count > 0 && v == last { continue; }
    body = body + v.to_str() + "\n";
    last = v;
    count += 1;
  }
  out.write("merged.txt", body.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + count.to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let names = src.list("")?;
  let dnames = dst.list("")?;
  let mut out: List<Str> = [];
  for name in names {
    let data = src.read(name)?;
    if dst.exists(name)? {
      let old = dst.read(name)?;
      if old == data {
        out.push("same " + name);
      } else {
        dst.write(name, data)?;
        out.push("updated " + name);
      }
    } else {
      dst.write(name, data)?;
      out.push("added " + name);
    }
  }
  let mut kept = 0;
  for n in dnames {
    if !names.contains(n) { kept += 1; }
  }
  out.push("kept " + kept.to_str());
  Ok(out.join("\n"))
}

struct Row { page: Str, n: Int }

fn main(input: Dir, counts: Kv) -> Result<Str, KvErr> {
  let mut local: Map<Str, Int> = Map::new();
  match input.read("visits.txt") {
    Ok(b) => {
      for line in b.to_str().lines() {
        let p = line.trim();
        if p == "" { continue; }
        local.insert(p, local.get(p).unwrap_or(0) + 1);
      }
    },
    Err(_) => {},
  }
  for p in local.keys() {
    counts.add("page:" + p, local.get(p).unwrap_or(0))?;
  }
  let mut rows: List<Row> = [];
  for k in counts.keys("page:")? {
    let n = match counts.get(k)? {
      Some(b) => b.to_str().parse_int().unwrap_or(0),
      None => 0,
    };
    rows.push(Row { page: k.strip_prefix("page:").unwrap_or(k), n: n });
  }
  rows.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.page < b.page));
  Ok(rows.map(|r| r.page + " " + r.n.to_str()).join("\n"))
}

fn key(id: Str) -> Str { "user:" + id }

fn handle(users: Kv, line: Str) -> Result<Str, KvErr> {
  let f = line.trim().split(" ").filter(|s| s != "");
  let bad = "bad " + line.trim();
  if f.len() == 0 { return Ok(bad); }
  let cmd = f[0];
  if cmd == "put" && f.len() == 4 {
    users.set(key(f[1]), (f[2] + " " + f[3]).to_bytes())?;
    return Ok("ok " + f[1]);
  }
  if cmd == "rename" && f.len() == 3 {
    return match users.get(key(f[1]))? {
      Some(b) => {
        let p = b.to_str().split(" ");
        users.set(key(f[1]), (f[2] + " " + p[1]).to_bytes())?;
        Ok("ok " + f[1])
      },
      None => Ok("missing " + f[1]),
    };
  }
  if cmd == "get" && f.len() == 2 {
    return match users.get(key(f[1]))? {
      Some(b) => {
        let p = b.to_str().split(" ");
        Ok("{\"id\":" + Json::Str(f[1]).to_json() + ",\"name\":" + Json::Str(p[0]).to_json() + ",\"email\":" + Json::Str(p[1]).to_json() + "}")
      },
      None => Ok("missing " + f[1]),
    };
  }
  if cmd == "del" && f.len() == 2 {
    return match users.get(key(f[1]))? {
      Some(b) => {
        users.delete(key(f[1]))?;
        Ok("ok " + f[1])
      },
      None => Ok("missing " + f[1]),
    };
  }
  if cmd == "count" && f.len() == 1 {
    let ks = users.keys("user:")?;
    return Ok("count " + ks.len().to_str());
  }
  Ok(bad)
}

fn main(input: Dir, users: Kv) -> Result<Str, KvErr> {
  let Ok(bytes) = input.read("commands.txt") else { return Ok(""); };
  let mut out: List<Str> = [];
  for line in bytes.to_str().lines() {
    if line.trim() == "" { continue; }
    let r = handle(users, line)?;
    out.push(r);
  }
  Ok(out.join("\n"))
}

fn main(input: Dir, state: Kv) -> Result<Str, KvErr> {
  let text = match input.read("events.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  let mut applied = 0;
  let mut duplicate = 0;
  let mut rejected = 0;
  for raw in text.lines() {
    let line = raw.trim();
    if line == "" { continue; }
    let Ok(doc) = line.parse_json() else { rejected += 1; continue; };
    let Some(_) = doc.as_map() else { rejected += 1; continue; };
    let Some(id) = doc.get("id").and_then(|v| v.as_str()) else { rejected += 1; continue; };
    let Some(account) = doc.get("account").and_then(|v| v.as_str()) else { rejected += 1; continue; };
    let Some(cents) = doc.get("cents").and_then(|v| v.as_int()) else { rejected += 1; continue; };
    if id.len() > 500 || account.len() > 500 { rejected += 1; continue; }
    let claimed = state.swap("seen:" + id, None, Some("1".to_bytes()))?;
    if claimed {
      let _ = state.add("bal:" + account, cents)?;
      applied += 1;
    } else {
      duplicate += 1;
    }
  }
  let mut out = "applied " + applied.to_str() + " duplicate " + duplicate.to_str() + " rejected " + rejected.to_str();
  for k in state.keys("bal:")? {
    let name = k.strip_prefix("bal:").unwrap_or(k);
    let val = match state.get(k)? {
      Some(b) => b.to_str(),
      None => "0",
    };
    out = out + "\n" + name + " " + val;
  }
  Ok(out)
}

enum Failed { Io(IoErr), Kv(KvErr) }

fn main(input: Dir, limits: Kv) -> Result<Str, Failed> {
  let text = input.read("requests.txt").map_err(|e| Failed::Io(e))?.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line == "" { continue; }
    let f = line.split(" ");
    if f.len() != 2 { continue; }
    let Some(t) = f[0].parse_int() else { continue; };
    let client = f[1];
    if client == "" { continue; }
    let key = "rl:" + client + ":" + (t / 60).to_str();
    let cur = match limits.get(key).map_err(|e| Failed::Kv(e))? {
      Some(b) => b.to_str().parse_int().unwrap_or(0),
      None => 0,
    };
    if cur < 3 {
      limits.add(key, 1).map_err(|e| Failed::Kv(e))?;
      out.push(f[0] + " " + client + " allow");
    } else {
      out.push(f[0] + " " + client + " deny");
    }
  }
  Ok(out.join("\n"))
}

struct Row { name: Str, pts: Int, played: Int }

fn bump(board: Kv, name: Str, pts: Int) -> Result<(), KvErr> {
  board.add("p:" + name, pts)?;
  board.add("g:" + name, 1)?;
  Ok(())
}

fn num(board: Kv, key: Str) -> Result<Int, KvErr> {
  let v = match board.get(key)? {
    Some(b) => b.to_str().parse_int().unwrap_or(0),
    None => 0,
  };
  Ok(v)
}

fn main(input: Dir, board: Kv) -> Result<Str, KvErr> {
  let text = match input.read("games.txt") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  for line in text.lines() {
    let f = line.trim().split(" ");
    if f.len() == 2 {
      if f[0] == "" || f[1] == "" { continue; }
      bump(board, f[0], 3)?;
      bump(board, f[1], 0)?;
    } else if f.len() == 3 {
      if f[2] != "draw" || f[0] == "" || f[1] == "" { continue; }
      bump(board, f[0], 1)?;
      bump(board, f[1], 1)?;
    }
  }
  let mut rows: List<Row> = [];
  for k in board.keys("p:")? {
    let name = k.strip_prefix("p:").unwrap_or(k);
    let pts = num(board, k)?;
    let played = num(board, "g:" + name)?;
    rows.push(Row { name: name, pts: pts, played: played });
  }
  rows.sort_by(|a, b| a.pts > b.pts
    || (a.pts == b.pts && (a.played < b.played
      || (a.played == b.played && a.name < b.name))));
  let n = 3.min(rows.len());
  let mut out: List<Str> = [];
  for i in 0..n {
    let r = rows[i];
    out.push((i + 1).to_str() + ". " + r.name + " " + r.pts.to_str() + " " + r.played.to_str());
  }
  Ok(out.join("\n"))
}

enum Failed { Io(IoErr), Db(DbErr) }

fn text(row: List<SqlValue>, i: Int) -> Str { match row[i] { SqlValue::Text(s) => s, _ => "" } }
fn int(row: List<SqlValue>, i: Int) -> Int { match row[i] { SqlValue::Int(n) => n, _ => 0 } }

fn main(input: Dir, shop: Db) -> Result<Str, Failed> {
  let body = input.read("orders.csv").map_err(|e| Failed::Io(e))?.to_str();
  shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", []).map_err(|e| Failed::Db(e))?;
  let lines = body.lines();
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  let mut i = 1;
  while i < lines.len() {
    let line = lines[i];
    i += 1;
    if line.trim() == "" { continue; }
    let f = line.split(",");
    if f.len() != 5 { rejected += 1; continue; }
    let Some(id) = f[0].trim().parse_int() else { rejected += 1; continue; };
    let Some(qty) = f[3].trim().parse_int() else { rejected += 1; continue; };
    let Some(cents) = f[4].trim().parse_int() else { rejected += 1; continue; };
    let n = shop.exec(
      "INSERT INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?) ON CONFLICT(order_id) DO NOTHING",
      [SqlValue::Int(id), SqlValue::Text(f[1].trim()), SqlValue::Text(f[2].trim()), SqlValue::Int(qty), SqlValue::Int(cents)]
    ).map_err(|e| Failed::Db(e))?;
    if n > 0 { imported += 1; } else { skipped += 1; }
  }
  let rows = shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ).map_err(|e| Failed::Db(e))?;
  let mut out: List<Str> = ["imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str()];
  for r in rows {
    out.push(text(r, 0) + " " + int(r, 1).to_str() + " " + int(r, 2).to_str());
  }
  Ok(out.join("\n"))
}

struct Agg { country: Str, customers: Int, orders: Int, revenue: Int, top: Str, top_rev: Int }

fn text(row: List<SqlValue>, i: Int) -> Str { match row[i] { SqlValue::Text(s) => s, _ => "" } }
fn int(row: List<SqlValue>, i: Int) -> Int { match row[i] { SqlValue::Int(n) => n, _ => 0 } }

fn main(shop: Db) -> Result<Str, DbErr> {
  let rows = shop.query(
    "SELECT c.id, c.name, c.country, COUNT(*), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01' GROUP BY c.id, c.name, c.country ORDER BY c.id",
    [])?;
  let mut m: Map<Str, Agg> = Map::new();
  let mut total_orders = 0;
  let mut total_rev = 0;
  for r in rows {
    let name = text(r, 1);
    let country = text(r, 2);
    let n = int(r, 3);
    let rev = int(r, 4);
    total_orders += n;
    total_rev += rev;
    match m.get(country) {
      Some(a) => {
        let better = rev > a.top_rev;
        m.insert(country, Agg {
          customers: a.customers + 1,
          orders: a.orders + n,
          revenue: a.revenue + rev,
          top: if better { name } else { a.top },
          top_rev: if better { rev } else { a.top_rev },
          ..a
        });
      }
      None => {
        m.insert(country, Agg { country: country, customers: 1, orders: n, revenue: rev, top: name, top_rev: rev });
      }
    }
  }
  let mut list: List<Agg> = [];
  for k in m.keys() {
    match m.get(k) {
      Some(a) => list.push(a),
      None => {}
    }
  }
  list.sort_by(|a, b| a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country));
  let mut lines: List<Str> = [];
  for a in list {
    lines.push(a.country + " customers=" + a.customers.to_str() + " orders=" + a.orders.to_str() + " revenue=" + a.revenue.to_str() + " top=" + a.top);
  }
  lines.push("total orders=" + total_orders.to_str() + " revenue=" + total_rev.to_str());
  Ok(lines.join("\n"))
}

struct Move { sku: Str, delta: Int }
struct Batch { name: Str, moves: List<Move>, bad: Bool }

fn parse_move(line: Str) -> Option<Move> {
  let f = line.split(" ");
  if f.len() != 2 { return None; }
  let q = f[1];
  let mut sign = 0;
  if q.starts_with("+") { sign = 1; } else if q.starts_with("-") { sign = -1; } else { return None; }
  let digits = q.slice(1, q.len());
  if digits.len() == 0 { return None; }
  for b in digits.to_bytes() {
    if b < 48 || b > 57 { return None; }
  }
  let n = digits.parse_int()?;
  if n <= 0 { return None; }
  Some(Move { sku: f[0], delta: sign * n })
}

fn parse_batches(text: Str) -> List<Batch> {
  let mut batches: List<Batch> = [];
  let mut started = false;
  let mut name = "";
  let mut moves: List<Move> = [];
  let mut bad = false;
  for raw in text.lines() {
    let line = raw.trim();
    if line == "" { continue; }
    if let Some(rest) = line.strip_prefix("batch ") {
      if started {
        batches.push(Batch { name: name, moves: moves, bad: bad });
      }
      started = true;
      name = rest.trim();
      moves = [];
      bad = false;
    } else if started {
      match parse_move(line) {
        Some(m) => moves.push(m),
        None => bad = true,
      }
    }
  }
  if started {
    batches.push(Batch { name: name, moves: moves, bad: bad });
  }
  batches
}

fn int(v: SqlValue) -> Int { match v { SqlValue::Int(n) => n, _ => 0 } }
fn text(v: SqlValue) -> Str { match v { SqlValue::Text(s) => s, _ => "" } }

fn main(input: Dir, stock: Db) -> Result<Str, DbErr> {
  let Ok(bytes) = input.read("moves.txt") else { return Ok(""); };
  let batches = parse_batches(bytes.to_str());

  stock.exec("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)", [])?;
  stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", [])?;

  let mut qty: Map<Str, Int> = Map::new();
  let rows = stock.query("SELECT sku, qty FROM stock", [])?;
  for r in rows { qty.insert(text(r[0]), int(r[1])); }
  let mut applied: Map<Str, Int> = Map::new();
  let arows = stock.query("SELECT name FROM applied", [])?;
  for r in arows { applied.insert(text(r[0]), 1); }

  let mut out: List<Str> = [];
  for b in batches {
    if applied.get(b.name).is_some() {
      out.push(b.name + " skipped");
      continue;
    }
    let mut w = qty;
    let mut ok = !b.bad;
    if ok {
      for m in b.moves {
        let cur = w.get(m.sku).unwrap_or(0);
        if cur + m.delta < 0 { ok = false; break; }
        w.insert(m.sku, cur + m.delta);
      }
    }
    if ok {
      let mut stmts: List<Str> = ["INSERT INTO applied (name) VALUES (?)"];
      let mut params: List<List<SqlValue>> = [[SqlValue::Text(b.name)]];
      for m in b.moves {
        stmts.push("INSERT INTO stock (sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = qty + excluded.qty");
        params.push([SqlValue::Text(m.sku), SqlValue::Int(m.delta)]);
      }
      stock.transaction(stmts, params)?;
      qty = w;
      applied.insert(b.name, 1);
      out.push(b.name + " applied");
    } else {
      out.push(b.name + " rejected");
    }
  }
  for k in qty.keys() {
    let n = qty.get(k).unwrap_or(0);
    if n != 0 { out.push(k + " " + n.to_str()); }
  }
  Ok(out.join("\n"))
}

enum Failed { Io(IoErr), Db(DbErr) }

fn text(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn main(input: Dir, crm: Db) -> Result<Str, Failed> {
  let raw = input.read("contacts.csv").map_err(|e| Failed::Io(e))?.to_str();
  crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", []).map_err(|e| Failed::Db(e))?;
  let lines = raw.lines();
  let mut ins = 0;
  let mut upd = 0;
  let mut same = 0;
  let mut rej = 0;
  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let f = line.split(",");
    if f.len() != 3 { rej += 1; continue; }
    let email = f[0].trim().to_lowercase();
    if !email.contains("@") { rej += 1; continue; }
    let name = f[1].trim();
    let phone = f[2].trim();
    let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)]).map_err(|e| Failed::Db(e))?;
    if rows.len() == 0 {
      crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)", [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)]).map_err(|e| Failed::Db(e))?;
      ins += 1;
    } else {
      let row = rows[0];
      if text(row[0]) != name || text(row[1]) != phone {
        crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?", [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)]).map_err(|e| Failed::Db(e))?;
        upd += 1;
      } else {
        same += 1;
      }
    }
  }
  let cnt = crm.query("SELECT COUNT(*) FROM contacts", []).map_err(|e| Failed::Db(e))?;
  let mut total = 0;
  if cnt.len() > 0 {
    total = match cnt[0][0] { SqlValue::Int(n) => n, _ => 0 };
  }
  let missing = crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", []).map_err(|e| Failed::Db(e))?;
  let mut out = "inserted " + ins.to_str() + " updated " + upd.to_str() + " unchanged " + same.to_str() + " rejected " + rej.to_str() + "\ncontacts " + total.to_str();
  for r in missing {
    out = out + "\nmissing phone: " + text(r[0]);
  }
  Ok(out)
}

struct Reply { status: Int, body: Json }
struct Entry { name: Str, count: Int }

fn valid(name: Str) -> Bool {
  let n = name.len();
  if n < 1 || n > 32 { return false; }
  for b in name.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 45;
    if !ok { return false; }
  }
  true
}

fn error(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m) }
}

fn entry_json(name: Str, count: Int) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(name));
  m.insert("count", Json::Num(count));
  Json::Obj(m)
}

fn read(store: Kv, key: Str) -> Result<Int, KvErr> {
  match store.get(key)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn top(store: Kv) -> Result<Reply, KvErr> {
  let keys = store.keys("c:")?;
  let mut rows: List<Entry> = [];
  for k in keys {
    let name = k.strip_prefix("c:").unwrap_or(k);
    let c = read(store, k)?;
    rows.push(Entry { name: name, count: c });
  }
  rows.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  let best = rows.slice(0, rows.len().min(3));
  let items = best.map(|e| entry_json(e.name, e.count));
  Ok(Reply { status: 200, body: Json::Arr(items) })
}

fn route(req: Incoming, store: Kv) -> Result<Reply, KvErr> {
  let method = req.method();
  let parts = req.target().split("/");
  if parts.len() == 2 && parts[0] == "" && parts[1] == "top" && method == "GET" {
    return top(store);
  }
  if parts.len() == 3 && parts[0] == "" {
    let name = parts[2];
    if parts[1] == "hit" && method == "POST" {
      if !valid(name) { return Ok(error(400, "bad name")); }
      let n = store.add("c:" + name, 1)?;
      return Ok(Reply { status: 200, body: entry_json(name, n) });
    }
    if parts[1] == "count" && method == "GET" {
      if !valid(name) { return Ok(error(400, "bad name")); }
      let n = read(store, "c:" + name)?;
      return Ok(Reply { status: 200, body: entry_json(name, n) });
    }
  }
  Ok(error(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<(), WebErr> {
  let r = route(req, counts).unwrap_or(error(500, "store failed"));
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes())
}

struct Reply { status: Int, body: Json }
struct Todo { id: Int, title: Str, done: Bool }
struct Upd { title: Option<Str>, done: Option<Bool> }

fn within(b: Bytes, i: Int, lo: Int, hi: Int) -> Bool {
  i < b.len() && b[i] >= lo && b[i] <= hi
}

fn valid(b: Bytes) -> Bool {
  let mut i = 0;
  let n = b.len();
  while i < n {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if !within(b, i + 1, 128, 191) { return false; }
      i += 2;
    } else if c >= 224 && c <= 239 {
      let lo = if c == 224 { 160 } else { 128 };
      let hi = if c == 237 { 159 } else { 191 };
      if !(within(b, i + 1, lo, hi) && within(b, i + 2, 128, 191)) { return false; }
      i += 3;
    } else if c >= 240 && c <= 244 {
      let lo = if c == 240 { 144 } else { 128 };
      let hi = if c == 244 { 143 } else { 191 };
      if !(within(b, i + 1, lo, hi) && within(b, i + 2, 128, 191) && within(b, i + 3, 128, 191)) { return false; }
      i += 4;
    } else {
      return false;
    }
  }
  true
}

fn error(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m) }
}

fn todo_json(t: Todo) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(t.id));
  m.insert("title", Json::Str(t.title));
  m.insert("done", Json::Bool(t.done));
  Json::Obj(m)
}

fn parse_todo(s: Str) -> Option<Todo> {
  let j = s.parse_json().ok()?;
  let id = j.get("id").and_then(|v| v.as_int())?;
  let title = j.get("title").and_then(|v| v.as_str())?;
  let done = j.get("done").and_then(|v| v.as_bool())?;
  Some(Todo { id: id, title: title, done: done })
}

fn load(store: Kv, id: Int) -> Result<Option<Todo>, KvErr> {
  match store.get("todo:" + id.to_str())? {
    Some(b) => Ok(parse_todo(b.to_str())),
    None => Ok(None),
  }
}

fn create(body: Bytes, store: Kv) -> Result<Reply, KvErr> {
  let bad = error(400, "title required");
  if !valid(body) { return Ok(bad); }
  let Ok(doc) = body.to_str().parse_json() else { return Ok(bad); };
  let Some(m) = doc.as_map() else { return Ok(bad); };
  let Some(title) = m.get("title").and_then(|j| j.as_str()) else { return Ok(bad); };
  let t = title.trim();
  if t == "" { return Ok(bad); }
  let id = store.add("next", 1)?;
  let todo = Todo { id: id, title: t, done: false };
  store.set("todo:" + id.to_str(), todo_json(todo).to_json().to_bytes())?;
  Ok(Reply { status: 201, body: todo_json(todo) })
}

fn list(target: Str, store: Kv) -> Result<Reply, KvErr> {
  let mut filter: Option<Bool> = None;
  let q = target.split("?");
  if q.len() >= 2 {
    for pair in q[1].split("&") {
      if pair == "done=true" { filter = Some(true); }
      else if pair == "done=false" { filter = Some(false); }
    }
  }
  let mut ids: List<Int> = [];
  for k in store.keys("todo:")? {
    if let Some(s) = k.strip_prefix("todo:") {
      if let Some(n) = s.parse_int() { ids.push(n); }
    }
  }
  ids.sort();
  let mut out: List<Json> = [];
  for id in ids {
    if let Some(t) = load(store, id)? {
      let keep = match filter {
        Some(f) => t.done == f,
        None => true,
      };
      if keep { out.push(todo_json(t)); }
    }
  }
  Ok(Reply { status: 200, body: Json::Arr(out) })
}

fn parse_upd(body: Bytes) -> Option<Upd> {
  if !valid(body) { return None; }
  let doc = body.to_str().parse_json().ok()?;
  let m = doc.as_map()?;
  let mut u = Upd { title: None, done: None };
  if let Some(j) = m.get("title") {
    let Some(s) = j.as_str() else { return None; };
    let t = s.trim();
    if t == "" { return None; }
    u.title = Some(t);
  }
  if let Some(j) = m.get("done") {
    let Some(d) = j.as_bool() else { return None; };
    u.done = Some(d);
  }
  Some(u)
}

fn patch(id: Int, body: Bytes, store: Kv) -> Result<Reply, KvErr> {
  let key = "todo:" + id.to_str();
  let Some(first) = store.get(key)? else { return Ok(error(404, "not found")); };
  let Some(u) = parse_upd(body) else { return Ok(error(400, "bad update")); };
  let mut cur = first;
  let mut tries = 0;
  while tries < 50 {
    let Some(t) = parse_todo(cur.to_str()) else { return Ok(error(404, "not found")); };
    let mut n = t;
    if let Some(s) = u.title { n.title = s; }
    if let Some(d) = u.done { n.done = d; }
    let nb = todo_json(n).to_json().to_bytes();
    if store.swap(key, Some(cur), Some(nb))? {
      return Ok(Reply { status: 200, body: todo_json(n) });
    }
    let Some(again) = store.get(key)? else { return Ok(error(404, "not found")); };
    cur = again;
    tries += 1;
  }
  Ok(error(500, "conflict"))
}

fn route(method: Str, target: Str, body: Bytes, store: Kv) -> Result<Reply, KvErr> {
  let path = target.split("?")[0];
  let parts = path.split("/");
  if parts.len() == 2 && parts[0] == "" && parts[1] == "todos" {
    if method == "POST" { return create(body, store); }
    if method == "GET" { return list(target, store); }
    return Ok(error(404, "not found"));
  }
  if parts.len() == 3 && parts[0] == "" && parts[1] == "todos" {
    let Some(id) = parts[2].parse_int() else { return Ok(error(404, "not found")); };
    if id.to_str() != parts[2] { return Ok(error(404, "not found")); }
    if method == "GET" {
      let Some(t) = load(store, id)? else { return Ok(error(404, "not found")); };
      return Ok(Reply { status: 200, body: todo_json(t) });
    }
    if method == "PATCH" { return patch(id, body, store); }
    if method == "DELETE" {
      let Some(t) = load(store, id)? else { return Ok(error(404, "not found")); };
      store.delete("todo:" + t.id.to_str())?;
      return Ok(Reply { status: 204, body: Json::Null });
    }
  }
  Ok(error(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Result<(), WebErr> {
  let r = route(req.method(), req.target(), req.body(), store).unwrap_or(error(500, "store failed"));
  if r.status == 204 {
    return res.send(204, [], [], "".to_bytes());
  }
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes())
}

struct Reply { status: Int, body: Json }

fn error(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m) }
}

fn text(row: List<SqlValue>, i: Int) -> Str { match row[i] { SqlValue::Text(s) => s, _ => "" } }
fn int(row: List<SqlValue>, i: Int) -> Int { match row[i] { SqlValue::Int(n) => n, _ => 0 } }

fn query(target: Str, key: Str) -> Option<Str> {
  let q = target.split("?");
  if q.len() < 2 { return None; }
  for pair in q[1].split("&") {
    if let Some(v) = pair.strip_prefix(key + "=") { return Some(v); }
  }
  None
}

fn setup(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS tags (note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE, pos INTEGER NOT NULL, tag TEXT NOT NULL, PRIMARY KEY (note_id, pos))", [])?;
  db.exec("CREATE INDEX IF NOT EXISTS tags_tag ON tags (tag)", [])?;
  Ok(())
}

fn create(db: Db, raw: Bytes) -> Result<Reply, DbErr> {
  let Ok(doc) = raw.to_str().parse_json() else { return Ok(error(400, "invalid note")); };
  let Some(title) = doc.get("title").and_then(|v| v.as_str()) else { return Ok(error(400, "invalid note")); };
  if title == "" { return Ok(error(400, "invalid note")); }
  let Some(body) = doc.get("body").and_then(|v| v.as_str()) else { return Ok(error(400, "invalid note")); };
  let mut tags: List<Str> = [];
  match doc.get("tags") {
    None => {},
    Some(t) => {
      let Some(items) = t.as_list() else { return Ok(error(400, "invalid note")); };
      for item in items {
        let Some(s) = item.as_str() else { return Ok(error(400, "invalid note")); };
        let l = s.to_lowercase();
        if !tags.contains(l) { tags.push(l); }
      }
    },
  }
  let rows = db.query("INSERT INTO notes (title, body) VALUES (?, ?) RETURNING id",
                      [SqlValue::Text(title), SqlValue::Text(body)])?;
  let id = int(rows[0], 0);
  if tags.len() > 0 {
    let mut stmts: List<Str> = [];
    let mut ps: List<List<SqlValue>> = [];
    for i in 0..tags.len() {
      stmts.push("INSERT INTO tags (note_id, pos, tag) VALUES (?, ?, ?)");
      ps.push([SqlValue::Int(id), SqlValue::Int(i), SqlValue::Text(tags[i])]);
    }
    db.transaction(stmts, ps)?;
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  Ok(Reply { status: 201, body: Json::Obj(m) })
}

fn get_note(db: Db, id: Int) -> Result<Reply, DbErr> {
  let rows = db.query("SELECT id, title, body FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { return Ok(error(404, "not found")); }
  let r = rows[0];
  let trows = db.query("SELECT tag FROM tags WHERE note_id = ? ORDER BY pos", [SqlValue::Int(id)])?;
  let tags: List<Json> = trows.map(|t| Json::Str(text(t, 0)));
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(int(r, 0)));
  m.insert("title", Json::Str(text(r, 1)));
  m.insert("body", Json::Str(text(r, 2)));
  m.insert("tags", Json::Arr(tags));
  Ok(Reply { status: 200, body: Json::Obj(m) })
}

fn list(db: Db, target: Str) -> Result<Reply, DbErr> {
  let mut sql = "SELECT id, title FROM notes WHERE 1 = 1";
  let mut params: List<SqlValue> = [];
  if let Some(t) = query(target, "tag") {
    sql = sql + " AND EXISTS (SELECT 1 FROM tags WHERE tags.note_id = notes.id AND tags.tag = ?)";
    params.push(SqlValue::Text(t.to_lowercase()));
  }
  if let Some(w) = query(target, "q") {
    sql = sql + " AND (instr(title, ?) > 0 OR instr(body, ?) > 0)";
    params.push(SqlValue::Text(w));
    params.push(SqlValue::Text(w));
  }
  sql = sql + " ORDER BY id DESC";
  let rows = db.query(sql, params)?;
  let items: List<Json> = rows.map(|r| {
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(int(r, 0)));
    m.insert("title", Json::Str(text(r, 1)));
    Json::Obj(m)
  });
  Ok(Reply { status: 200, body: Json::Arr(items) })
}

fn delete(db: Db, id: Int) -> Result<Reply, DbErr> {
  let n = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if n == 0 { return Ok(error(404, "not found")); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("deleted", Json::Num(id));
  Ok(Reply { status: 200, body: Json::Obj(m) })
}

fn route(req: Incoming, db: Db) -> Result<Reply, DbErr> {
  setup(db)?;
  let target = req.target();
  let path = target.split("?")[0];
  let method = req.method();
  if path == "/notes" {
    if method == "POST" { return create(db, req.body()); }
    if method == "GET" { return list(db, target); }
    return Ok(error(404, "not found"));
  }
  let parts = path.split("/");
  if parts.len() == 3 && parts[0] == "" && parts[1] == "notes" {
    let Some(id) = parts[2].parse_int() else { return Ok(error(404, "not found")); };
    if id.to_str() != parts[2] { return Ok(error(404, "not found")); }
    if method == "GET" { return get_note(db, id); }
    if method == "DELETE" { return delete(db, id); }
  }
  Ok(error(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<(), WebErr> {
  let r = route(req, db).unwrap_or(error(500, "internal error"));
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes())
}

struct Line { name: Str, text: Str }

enum Failed { Http(HttpErr), Json(Str) }

fn fmt(t: Int) -> Str {
  let a = if t < 0 { 0 - t } else { t };
  (if t < 0 { "-" } else { "" }) + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn station_text(api: Http, id: Str, name: Str) -> Str {
  let Ok(bytes) = api.get("/stations/" + id + "/readings") else { return name + " unavailable"; };
  let Ok(doc) = bytes.to_str().parse_json() else { return name + " unavailable"; };
  let readings = doc.get("readings").and_then(|v| v.as_list()).unwrap_or([]);
  let mut n = 0;
  let mut sum = 0;
  let mut lo = 0;
  let mut hi = 0;
  for r in readings {
    let Some(t) = r.get("temp").and_then(|v| v.as_int()) else { continue; };
    if n == 0 {
      lo = t;
      hi = t;
    } else {
      lo = lo.min(t);
      hi = hi.max(t);
    }
    sum += t;
    n += 1;
  }
  if n == 0 { return name + " no data"; }
  name + " min=" + fmt(lo) + " max=" + fmt(hi) + " avg=" + fmt(sum / n) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Failed> {
  let body = api.get("/stations").map_err(|e| Failed::Http(e))?.to_str();
  let doc = body.parse_json().map_err(|e| Failed::Json(e))?;
  let stations = doc.get("stations").and_then(|v| v.as_list()).unwrap_or([]);
  let mut lines: List<Line> = [];
  for s in stations {
    let id = s.get("id").and_then(|v| v.as_str()).unwrap_or("");
    let name = s.get("name").and_then(|v| v.as_str()).unwrap_or("");
    lines.push(Line { name: name, text: station_text(api, id, name) });
  }
  lines.sort_by(|a, b| a.name < b.name);
  Ok(lines.map(|l| l.text).join("\n"))
}

enum Failed { Http(HttpErr), Json(Str), Status(Int) }

fn main(api: Http) -> Result<Str, Failed> {
  let mut page = 1;
  let mut done = false;
  let mut count = 0;
  let mut refunded = 0;
  let mut paid: Map<Str, Int> = Map::new();
  let mut best = -1;
  let mut largest = 0;
  let mut have = false;
  while !done {
    let body = api.get("/orders?page=" + page.to_str()).map_err(|e| Failed::Http(e))?.to_str();
    let doc = body.parse_json().map_err(|e| Failed::Json(e))?;
    for o in doc.get("orders").and_then(|v| v.as_list()).unwrap_or([]) {
      count += 1;
      let status = o.get("status").and_then(|v| v.as_str()).unwrap_or("");
      let id = o.get("id").and_then(|v| v.as_int()).unwrap_or(0);
      let cents = o.get("cents").and_then(|v| v.as_int()).unwrap_or(0);
      let cur = o.get("currency").and_then(|v| v.as_str()).unwrap_or("");
      if status == "refunded" { refunded += 1; }
      if status == "paid" {
        paid.insert(cur, paid.get(cur).unwrap_or(0) + cents);
        if !have || cents > best || (cents == best && id < largest) {
          best = cents;
          largest = id;
          have = true;
        }
      }
    }
    let next = doc.get("next").and_then(|v| v.as_int());
    match next {
      Some(n) => page = n,
      None => done = true,
    }
  }
  let mut pc: Map<Str, Json> = Map::new();
  for k in paid.keys() { pc.insert(k, Json::Num(paid.get(k).unwrap_or(0))); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("orders", Json::Num(count));
  m.insert("paid_cents", Json::Obj(pc));
  m.insert("refunded", Json::Num(refunded));
  m.insert("largest", if have { Json::Num(largest) } else { Json::Null });
  let r = api.send("POST", "/summaries", ["content-type: application/json"],
                   Json::Obj(m).to_json().to_bytes(), 0).map_err(|e| Failed::Http(e))?;
  if r.status != 201 { return Err(Failed::Status(r.status)); }
  let resp = r.body.to_str().parse_json().map_err(|e| Failed::Json(e))?;
  Ok(resp.get("id").and_then(|v| v.as_str()).unwrap_or(""))
}

fn touch(order: List<Str>, k: Str) -> List<Str> {
  let mut n: List<Str> = [k];
  for x in order {
    if x != k { n.push(x); }
  }
  n
}

fn without(order: List<Str>, k: Str) -> List<Str> {
  let mut n: List<Str> = [];
  for x in order {
    if x != k { n.push(x); }
  }
  n
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
  let text = input.read("ops.txt").map_err(|e| "read failed")?.to_str();
  let lines = text.lines();
  if lines.len() == 0 { return Err("empty"); }
  let cp = lines[0].split(" ");
  let cap = if cp.len() >= 2 { cp[1].parse_int().unwrap_or(1) } else { 1 };

  let mut order: List<Str> = [];
  let mut vals: Map<Str, Str> = Map::new();
  let mut hits = 0;
  let mut misses = 0;
  let mut ev = 0;
  let mut out: List<Str> = [];

  let raw = cache.get("state").map_err(|e| "kv failed")?;
  if let Some(b) = raw {
    let doc = b.to_str().parse_json().unwrap_or(Json::Null);
    let no_items: List<Json> = [];
    for j in doc.get("order").and_then(|v| v.as_list()).unwrap_or(no_items) {
      order.push(j.as_str().unwrap_or(""));
    }
    let empty: Map<Str, Json> = Map::new();
    let m = doc.get("vals").and_then(|v| v.as_map()).unwrap_or(empty);
    for k in m.keys() {
      vals.insert(k, m.get(k).and_then(|v| v.as_str()).unwrap_or(""));
    }
    hits = doc.get("hits").and_then(|v| v.as_int()).unwrap_or(0);
    misses = doc.get("misses").and_then(|v| v.as_int()).unwrap_or(0);
    ev = doc.get("ev").and_then(|v| v.as_int()).unwrap_or(0);
  }

  while order.len() > cap {
    let Some(k) = order.pop() else { break; };
    vals.remove(k);
    ev += 1;
    out.push("evict " + k);
  }

  for i in 1..lines.len() {
    let line = lines[i];
    if line == "" { continue; }
    let parts = line.split(" ");
    let op = parts[0];
    if op == "get" && parts.len() == 2 && parts[1] != "" {
      let k = parts[1];
      match vals.get(k) {
        Some(v) => {
          hits += 1;
          order = touch(order, k);
          out.push(k + "=" + v);
        }
        None => {
          misses += 1;
          out.push(k + " miss");
        }
      }
    } else if op == "del" && parts.len() == 2 && parts[1] != "" {
      let k = parts[1];
      if vals.get(k).is_some() {
        vals.remove(k);
        order = without(order, k);
      }
    } else if op == "put" && parts.len() >= 3 && parts[1] != "" {
      let k = parts[1];
      let value = line.slice(5 + k.len(), line.len());
      if value == "" {
        out.push("bad line " + (i + 1).to_str());
      } else {
        if vals.get(k).is_none() && order.len() >= cap {
          if let Some(old) = order.pop() {
            vals.remove(old);
            ev += 1;
            out.push("evict " + old);
          }
        }
        vals.insert(k, value);
        order = touch(order, k);
      }
    } else {
      out.push("bad line " + (i + 1).to_str());
    }
  }

  if order.len() == 0 {
    out.push("cache:");
  } else {
    out.push("cache: " + order.join(","));
  }
  out.push("stats hits " + hits.to_str() + " misses " + misses.to_str() + " evictions " + ev.to_str());

  let mut vm: Map<Str, Json> = Map::new();
  for k in vals.keys() {
    vm.insert(k, Json::Str(vals.get(k).unwrap_or("")));
  }
  let mut top: Map<Str, Json> = Map::new();
  top.insert("order", Json::Arr(order.map(|k| Json::Str(k))));
  top.insert("vals", Json::Obj(vm));
  top.insert("hits", Json::Num(hits));
  top.insert("misses", Json::Num(misses));
  top.insert("ev", Json::Num(ev));
  cache.set("state", Json::Obj(top).to_json().to_bytes()).map_err(|e| "kv failed")?;

  Ok(out.join("\n"))
}

fn join(xs: List<Str>) -> Str { xs.join(", ") }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("packages.json")?.to_str();
  let Ok(doc) = text.parse_json() else { return Ok("error: not an object"); };
  let Some(m) = doc.as_map() else { return Ok("error: not an object"); };
  let mut names: List<Str> = [];
  let mut raw: List<List<Str>> = [];
  let mut invalid: List<Str> = [];
  for k in m.keys() {
    let v = m.get(k).unwrap_or(Json::Null);
    let mut ok = false;
    let mut deps: List<Str> = [];
    if let Some(items) = v.as_list() {
      ok = true;
      for it in items {
        match it.as_str() {
          Some(s) => { if !deps.contains(s) { deps.push(s); } },
          None => ok = false,
        }
      }
    }
    if ok {
      names.push(k);
      raw.push(deps);
    } else {
      invalid.push(k);
    }
  }
  let n = names.len();
  let mut idx: Map<Str, Int> = Map::new();
  for i in 0..n { idx.insert(names[i], i); }
  let mut adj: List<List<Int>> = [];
  let mut radj: List<List<Int>> = [];
  let mut hasmiss: List<Bool> = [];
  let mut selfloop: List<Bool> = [];
  for i in 0..n {
    adj.push([]);
    radj.push([]);
    hasmiss.push(false);
    selfloop.push(false);
  }
  let mut miss: Map<Str, List<Str>> = Map::new();
  for i in 0..n {
    for d in raw[i] {
      match idx.get(d) {
        Some(j) => {
          adj[i].push(j);
          radj[j].push(i);
          if j == i { selfloop[i] = true; }
        },
        None => {
          hasmiss[i] = true;
          let mut cur: List<Str> = miss.get(d).unwrap_or([]);
          cur.push(names[i]);
          miss.insert(d, cur);
        },
      }
    }
  }
  // Kosaraju pass 1
  let mut visited: List<Bool> = [];
  let mut ptr: List<Int> = [];
  let mut comp: List<Int> = [];
  for i in 0..n {
    visited.push(false);
    ptr.push(0);
    comp.push(-1);
  }
  let mut order: List<Int> = [];
  for s in 0..n {
    if visited[s] { continue; }
    visited[s] = true;
    let mut stack: List<Int> = [s];
    while stack.len() > 0 {
      let v = stack[stack.len() - 1];
      if ptr[v] < adj[v].len() {
        let w = adj[v][ptr[v]];
        ptr[v] = ptr[v] + 1;
        if !visited[w] {
          visited[w] = true;
          stack.push(w);
        }
      } else {
        order.push(v);
        stack.pop();
      }
    }
  }
  // pass 2
  let mut c = 0;
  let mut members: List<List<Int>> = [];
  for i in 0..n {
    let s = order[n - 1 - i];
    if comp[s] >= 0 { continue; }
    comp[s] = c;
    let mut mem: List<Int> = [];
    let mut stack: List<Int> = [s];
    while stack.len() > 0 {
      let v = stack[stack.len() - 1];
      stack.pop();
      mem.push(v);
      for w in radj[v] {
        if comp[w] < 0 {
          comp[w] = c;
          stack.push(w);
        }
      }
    }
    members.push(mem);
    c += 1;
  }
  let mut cyc: List<Bool> = [];
  for i in 0..n {
    cyc.push(members[comp[i]].len() >= 2 || selfloop[i]);
  }
  let mut stage: List<Int> = [];
  for i in 0..n { stage.push(0); }
  for v in order {
    if cyc[v] || hasmiss[v] { continue; }
    let mut st = 1;
    let mut okb = true;
    for w in adj[v] {
      if stage[w] == 0 { okb = false; } else { st = st.max(stage[w] + 1); }
    }
    if okb { stage[v] = st; }
  }
  let mut lines: List<Str> = [];
  let mut maxs = 0;
  for i in 0..n { maxs = maxs.max(stage[i]); }
  for s in 1..maxs + 1 {
    let mut ps: List<Str> = [];
    for i in 0..n { if stage[i] == s { ps.push(names[i]); } }
    if ps.len() > 0 { lines.push("stage " + s.to_str() + ": " + join(ps)); }
  }
  for i in 0..n {
    if !cyc[i] { continue; }
    let mem = members[comp[i]];
    let mut ps: List<Str> = [];
    for j in 0..n { if comp[j] == comp[i] { ps.push(names[j]); } }
    if ps[0] == names[i] { lines.push("cycle: " + join(ps)); }
  }
  for k in miss.keys() {
    let by = miss.get(k).unwrap_or([]);
    lines.push("missing: " + k + " (needed by " + join(by) + ")");
  }
  if invalid.len() > 0 { lines.push("invalid: " + join(invalid)); }
  let mut blocked: List<Str> = [];
  let mut built = 0;
  for i in 0..n {
    if stage[i] > 0 { built += 1; } else if !cyc[i] { blocked.push(names[i]); }
  }
  if blocked.len() > 0 { lines.push("blocked: " + join(blocked)); }
  lines.push("built " + built.to_str() + " of " + n.to_str());
  Ok(lines.join("\n"))
}

struct Bk { room: Str, day: Str, start: Int, end: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Cf { s: Int, text: Str }

fn pad(n: Int) -> Str { if n < 10 { "0" + n.to_str() } else { n.to_str() } }

fn fmt(t: Int) -> Str { pad(t / 60) + ":" + pad(t % 60) }

fn tm(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 5 || b[2] != 58 { return None; }
  for i in [0, 1, 3, 4] {
    if b[i] < 48 || b[i] > 57 { return None; }
  }
  let h = (b[0] - 48) * 10 + (b[1] - 48);
  let m = (b[3] - 48) * 10 + (b[4] - 48);
  if m > 59 { return None; }
  if h > 24 || (h == 24 && m != 0) { return None; }
  Some(h * 60 + m)
}

fn parse(line: Str) -> Option<Bk> {
  let f = line.split(",");
  if f.len() != 5 { return None; }
  let s = tm(f[2])?;
  let e = tm(f[3])?;
  if e <= s { return None; }
  Some(Bk { room: f[0], day: f[1], start: s, end: e, who: f[4] })
}

fn ivs(ts: List<Iv>) -> Str {
  ts.map(|t| fmt(t.s) + "-" + fmt(t.e)).join(", ")
}

fn report(bks: List<Bk>) -> Str {
  let mut sorted = bks;
  sorted.sort_by_key(|b| b.start);
  let mut busy: List<Iv> = [];
  let mut cs = sorted[0].start;
  let mut ce = sorted[0].end;
  for i in 1..sorted.len() {
    let b = sorted[i];
    if b.start <= ce {
      ce = ce.max(b.end);
    } else {
      busy.push(Iv { s: cs, e: ce });
      cs = b.start;
      ce = b.end;
    }
  }
  busy.push(Iv { s: cs, e: ce });
  let mut free: List<Iv> = [];
  let mut cursor = 540;
  for v in busy {
    let ge = v.s.min(1080);
    if ge - cursor >= 30 { free.push(Iv { s: cursor, e: ge }); }
    cursor = cursor.max(v.e);
  }
  if 1080 - cursor >= 30 { free.push(Iv { s: cursor, e: 1080 }); }
  let mut cf: List<Cf> = [];
  for i in 0..sorted.len() {
    for j in (i + 1)..sorted.len() {
      let a = sorted[i];
      let b = sorted[j];
      let os = a.start.max(b.start);
      let oe = a.end.min(b.end);
      if os < oe {
        let names = if a.who < b.who { a.who + "/" + b.who } else { b.who + "/" + a.who };
        cf.push(Cf { s: os, text: "  conflict " + names + " " + fmt(os) + "-" + fmt(oe) });
      }
    }
  }
  cf.sort_by(|x, y| x.s < y.s || (x.s == y.s && x.text < y.text));
  let mut out: List<Str> = [];
  out.push(sorted[0].room + " " + sorted[0].day);
  out.push("  busy " + ivs(busy));
  if free.len() == 0 { out.push("  free none"); } else { out.push("  free " + ivs(free)); }
  for c in cf { out.push(c.text); }
  out.join("\n")
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut groups: Map<Str, List<Bk>> = Map::new();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut skipped: List<Int> = [];
  for i in 1..lines.len() {
    let line = lines[i].trim();
    if line == "" { continue; }
    let Some(b) = parse(line) else { skipped.push(i + 1); continue; };
    if seen.get(line).is_some() { continue; }
    seen.insert(line, true);
    let k = b.room + "\0" + b.day;
    let mut lst = groups.get(k).unwrap_or([]);
    lst.push(b);
    groups.insert(k, lst);
  }
  let mut out: List<Str> = [];
  for k in groups.keys() {
    out.push(report(groups.get(k).unwrap_or([])));
  }
  if skipped.len() == 0 {
    out.push("skipped: none");
  } else {
    out.push("skipped: " + skipped.map(|n| n.to_str()).join(", "));
  }
  Ok(out.join("\n"))
}

struct Issue { path: Str, msg: Str }

fn issue(path: Str, msg: Str) -> Issue {
  Issue { path: path, msg: msg }
}

fn bounds(schema: Json, v: Json, path: Str) -> List<Issue> {
  let mut out: List<Issue> = [];
  let mn = schema.get("minimum").and_then(|j| j.as_int());
  let mx = schema.get("maximum").and_then(|j| j.as_int());
  let below = match v {
    Json::Num(n) => mn.map(|b| n < b).unwrap_or(false),
    Json::Float(f) => mn.map(|b| f < b.to_float()).unwrap_or(false),
    _ => false,
  };
  let above = match v {
    Json::Num(n) => mx.map(|b| n > b).unwrap_or(false),
    Json::Float(f) => mx.map(|b| f > b.to_float()).unwrap_or(false),
    _ => false,
  };
  if below {
    out.push(issue(path, "less than " + mn.unwrap_or(0).to_str()));
  } else if above {
    out.push(issue(path, "greater than " + mx.unwrap_or(0).to_str()));
  }
  out
}

fn check(schema: Json, v: Json, path: Str) -> List<Issue> {
  let t = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  let mut out: List<Issue> = [];
  match t {
    "object" => {
      match v {
        Json::Obj(m) => {
          let empty: Map<Str, Json> = Map::new();
          let props = schema.get("properties").and_then(|j| j.as_map()).unwrap_or(empty);
          let req = schema.get("required").and_then(|j| j.as_list()).unwrap_or([]);
          for r in req {
            if let Some(name) = r.as_str() {
              if m.get(name).is_none() {
                out.push(issue(path + "." + name, "missing required field"));
              }
            }
          }
          let closed = schema.get("additional").and_then(|j| j.as_bool()) == Some(false);
          if closed {
            for k in m.keys() {
              if props.get(k).is_none() {
                out.push(issue(path + "." + k, "unexpected field"));
              }
            }
          }
          for k in props.keys() {
            if let Some(child) = m.get(k) {
              let sub = props.get(k).unwrap_or(Json::Null);
              for e in check(sub, child, path + "." + k) { out.push(e); }
            }
          }
        }
        _ => { out.push(issue(path, "expected object")); }
      }
    }
    "array" => {
      match v {
        Json::Arr(xs) => {
          if let Some(n) = schema.get("min_items").and_then(|j| j.as_int()) {
            if xs.len() < n {
              out.push(issue(path, "fewer than " + n.to_str() + " items"));
            }
          }
          if let Some(s) = schema.get("items") {
            for i in 0..xs.len() {
              for e in check(s, xs[i], path + "[" + i.to_str() + "]") { out.push(e); }
            }
          }
        }
        _ => { out.push(issue(path, "expected array")); }
      }
    }
    "string" => {
      match v {
        Json::Str(s) => {
          let len = s.chars().len();
          let minl = schema.get("min_length").and_then(|j| j.as_int());
          let maxl = schema.get("max_length").and_then(|j| j.as_int());
          let en = schema.get("enum").and_then(|j| j.as_list());
          let bad_enum = en.map(|l| !l.any(|j| j.as_str() == Some(s))).unwrap_or(false);
          if minl.map(|n| len < n).unwrap_or(false) {
            out.push(issue(path, "shorter than " + minl.unwrap_or(0).to_str()));
          } else if maxl.map(|n| len > n).unwrap_or(false) {
            out.push(issue(path, "longer than " + maxl.unwrap_or(0).to_str()));
          } else if bad_enum {
            out.push(issue(path, "not in enum"));
          }
        }
        _ => { out.push(issue(path, "expected string")); }
      }
    }
    "integer" => {
      match v {
        Json::Num(_) => { for e in bounds(schema, v, path) { out.push(e); } }
        _ => { out.push(issue(path, "expected integer")); }
      }
    }
    "number" => {
      match v {
        Json::Num(_) => { for e in bounds(schema, v, path) { out.push(e); } }
        Json::Float(_) => { for e in bounds(schema, v, path) { out.push(e); } }
        _ => { out.push(issue(path, "expected number")); }
      }
    }
    "boolean" => {
      match v {
        Json::Bool(_) => {}
        _ => { out.push(issue(path, "expected boolean")); }
      }
    }
    "null" => {
      match v {
        Json::Null => {}
        _ => { out.push(issue(path, "expected null")); }
      }
    }
    _ => {}
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let stext = input.read("schema.json")?.to_str();
  let Ok(schema) = stext.parse_json() else { return Ok("bad schema"); };
  let text = input.read("records.jsonl")?.to_str();
  let lines = text.lines();
  let mut out: List<Str> = [];
  let mut total = 0;
  let mut valid = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    total += 1;
    let prefix = "line " + (i + 1).to_str() + ": ";
    let Ok(rec) = line.parse_json() else {
      out.push(prefix + "invalid JSON");
      continue;
    };
    let mut rows = check(schema, rec, "$");
    if rows.len() == 0 {
      valid += 1;
      out.push(prefix + "ok");
      continue;
    }
    rows.sort_by(|a, b| a.path < b.path || (a.path == b.path && a.msg < b.msg));
    for r in rows {
      out.push(prefix + r.path + ": " + r.msg);
    }
  }
  out.push("valid " + valid.to_str() + " of " + total.to_str());
  Ok(out.join("\n"))
}

enum Failed { Io(IoErr), Kv(KvErr) }

struct Rec { id: Str, version: Int, doc: Json }

fn parse_line(line: Str) -> Option<Rec> {
  let Ok(doc) = line.parse_json() else { return None; };
  let id = doc.get("id").and_then(|j| j.as_str())?;
  let version = doc.get("version").and_then(|j| j.as_int())?;
  Some(Rec { id: id, version: version, doc: doc })
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Failed> {
  let text = input.read("records.jsonl").map_err(|e| Failed::Io(e))?.to_str();
  let lines = text.lines();
  let mut recs: Map<Str, Rec> = Map::new();
  let mut out: List<Str> = [];
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    if let Some(r) = parse_line(line) {
      recs.insert(r.id, r);
    } else {
      out.push("line " + (i + 1).to_str() + " invalid");
    }
  }
  let ids = recs.keys();
  // code: 0 unchanged, 1 synced, 3 failed, 400..499 rejected status
  let mut code: Map<Str, Int> = Map::new();
  let mut pending: List<Str> = [];
  for id in ids {
    code.insert(id, 0);
    let Some(rec) = recs.get(id) else { continue; };
    let last = state.get("v:" + id).map_err(|e| Failed::Kv(e))?;
    let lastv: Option<Int> = match last {
      Some(b) => b.to_str().parse_int(),
      None => None,
    };
    let push = match lastv {
      Some(v) => rec.version > v,
      None => true,
    };
    if push { pending.push(id); }
  }
  for attempt in 0..3 {
    if pending.len() == 0 { break; }
    let mut next: List<Str> = [];
    for id in pending {
      let Some(rec) = recs.get(id) else { continue; };
      let r = api.send("PUT", "/records/" + id, ["content-type: application/json"],
                       rec.doc.to_json().to_bytes(), 0);
      match r {
        Ok(resp) => {
          if resp.status >= 200 && resp.status < 300 {
            state.set("v:" + id, rec.version.to_str().to_bytes()).map_err(|e| Failed::Kv(e))?;
            code.insert(id, 1);
          } else if resp.status >= 400 && resp.status < 500 {
            code.insert(id, resp.status);
          } else {
            next.push(id);
          }
        },
        Err(_) => { next.push(id); },
      }
    }
    pending = next;
  }
  for id in pending { code.insert(id, 3); }
  let mut s = 0;
  let mut u = 0;
  let mut rj = 0;
  let mut f = 0;
  for id in recs.keys() {
    let c = code.get(id).unwrap_or(0);
    if c == 0 { u += 1; out.push(id + " unchanged"); }
    else if c == 1 { s += 1; out.push(id + " synced"); }
    else if c == 3 { f += 1; out.push(id + " failed"); }
    else { rj += 1; out.push(id + " rejected " + c.to_str()); }
  }
  out.push("synced " + s.to_str() + " unchanged " + u.to_str() + " rejected " + rj.to_str() + " failed " + f.to_str());
  Ok(out.join("\n"))
}

enum Failed { Db(DbErr), Log(LogErr), Io(IoErr) }

struct Outcome { kind: Int, msg: Str }

fn pad(n: Int, w: Int) -> Str {
  let mut s = n.to_str();
  while s.len() < w { s = "0" + s; }
  s
}

fn fmt_time(ms: Int) -> Str {
  let secs = ms / 1000;
  let days = secs / 86400;
  let rem = secs % 86400;
  let z = days + 719468;
  let era = z / 146097;
  let doe = z - era * 146097;
  let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  let y0 = yoe + era * 400;
  let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  let mp = (5 * doy + 2) / 153;
  let d = doy - (153 * mp + 2) / 5 + 1;
  let m = if mp < 10 { mp + 3 } else { mp - 9 };
  let y = if m <= 2 { y0 + 1 } else { y0 };
  pad(y, 4) + "-" + pad(m, 2) + "-" + pad(d, 2) + "T" + pad(rem / 3600, 2) + ":" + pad((rem % 3600) / 60, 2) + ":" + pad(rem % 60, 2) + "Z"
}

fn int(row: List<SqlValue>, i: Int) -> Int { match row[i] { SqlValue::Int(n) => n, _ => 0 } }
fn text(row: List<SqlValue>, i: Int) -> Str { match row[i] { SqlValue::Text(s) => s, _ => "" } }

fn fail(m: Str) -> Outcome { Outcome { kind: 1, msg: m } }

// the balance of an open (not closed) account
fn live(db: Db, name: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT balance FROM accounts WHERE name = ? AND closed = 0", [SqlValue::Text(name)])?;
  if rows.len() == 0 { return Ok(None); }
  Ok(Some(int(rows[0], 0)))
}

fn run_op(db: Db, line: Str, now: Str) -> Result<Outcome, DbErr> {
  let w = line.split(" ");
  let op = w[0];
  let ok = Outcome { kind: 0, msg: "" };
  if op == "open" {
    if w.len() != 3 { return Ok(fail("malformed")); }
    let Some(c) = w[2].parse_int() else { return Ok(fail("malformed")); };
    if c < 0 { return Ok(fail("bad amount")); }
    let rows = db.query("SELECT balance FROM accounts WHERE name = ?", [SqlValue::Text(w[1])])?;
    if rows.len() > 0 { return Ok(fail("account exists")); }
    db.exec("INSERT INTO accounts (name, balance, last, closed) VALUES (?, ?, ?, 0)",
            [SqlValue::Text(w[1]), SqlValue::Int(c), SqlValue::Text(now)])?;
    return Ok(ok);
  }
  if op == "close" {
    if w.len() != 2 { return Ok(fail("malformed")); }
    let Some(b) = live(db, w[1])? else { return Ok(fail("no account " + w[1])); };
    if b != 0 { return Ok(fail("balance not zero")); }
    db.exec("UPDATE accounts SET closed = 1 WHERE name = ?", [SqlValue::Text(w[1])])?;
    return Ok(ok);
  }
  if op == "transfer" {
    if w.len() != 5 { return Ok(fail("malformed")); }
    let Some(c) = w[4].parse_int() else { return Ok(fail("malformed")); };
    let id = w[1];
    let from = w[2];
    let to = w[3];
    let prev = db.query("SELECT src, dst, cents FROM transfers WHERE id = ?", [SqlValue::Text(id)])?;
    if prev.len() > 0 {
      if text(prev[0], 0) == from && text(prev[0], 1) == to && int(prev[0], 2) == c {
        return Ok(Outcome { kind: 2, msg: "" });
      }
      return Ok(fail("id reused"));
    }
    if c <= 0 { return Ok(fail("bad amount")); }
    if from == to { return Ok(fail("same account")); }
    let Some(fb) = live(db, from)? else { return Ok(fail("no account " + from)); };
    let Some(tb) = live(db, to)? else { return Ok(fail("no account " + to)); };
    if fb < c { return Ok(fail("insufficient funds")); }
    if tb > 9223372036854775807 - c { return Ok(fail("overflow")); }
    db.transaction(
      ["UPDATE accounts SET balance = ?, last = ? WHERE name = ?",
       "UPDATE accounts SET balance = ?, last = ? WHERE name = ?",
       "INSERT INTO transfers (id, src, dst, cents) VALUES (?, ?, ?, ?)"],
      [[SqlValue::Int(fb - c), SqlValue::Text(now), SqlValue::Text(from)],
       [SqlValue::Int(tb + c), SqlValue::Text(now), SqlValue::Text(to)],
       [SqlValue::Text(id), SqlValue::Text(from), SqlValue::Text(to), SqlValue::Int(c)]])?;
    return Ok(ok);
  }
  Ok(fail("malformed"))
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Failed> {
  let now = fmt_time(clock.now_ms());
  db.exec("CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, last TEXT NOT NULL, closed INTEGER NOT NULL)", []).map_err(|e| Failed::Db(e))?;
  db.exec("CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)", []).map_err(|e| Failed::Db(e))?;
  let text_in = input.read("ops.txt").map_err(|e| Failed::Io(e))?.to_str();
  let lines = text_in.lines();
  let mut k = 0;
  let mut f = 0;
  let mut d = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let r = run_op(db, line, now).map_err(|e| Failed::Db(e))?;
    if r.kind == 0 {
      k += 1;
    } else if r.kind == 2 {
      d += 1;
    } else {
      f += 1;
      log.write(now + " line " + (i + 1).to_str() + ": " + r.msg).map_err(|e| Failed::Log(e))?;
    }
  }
  let rows = db.query("SELECT name, balance, last FROM accounts WHERE closed = 0 ORDER BY name", []).map_err(|e| Failed::Db(e))?;
  let mut out: List<Str> = ["ok " + k.to_str() + " failed " + f.to_str() + " duplicate " + d.to_str()];
  for r in rows {
    out.push(text(r, 0) + " " + int(r, 1).to_str() + " last " + text(r, 2));
  }
  Ok(out.join("\n"))
}

struct Reply { status: Int, body: Json }
struct Cred { name: Str, password: Str }
struct Sess { name: Str, expiry: Int }

fn obj1(k: Str, v: Json) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, v);
  Json::Obj(m)
}

fn error(status: Int, msg: Str) -> Reply {
  Reply { status: status, body: obj1("error", Json::Str(msg)) }
}

fn header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() { if names[i] == name { return Some(values[i]); } }
  None
}

fn valid_name(s: Str) -> Bool {
  let b = s.to_bytes();
  if b.len() < 3 || b.len() > 20 { return false; }
  for i in 0..b.len() {
    let c = b[i];
    if !((c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c == 95) { return false; }
  }
  true
}

fn creds(req: Incoming) -> Option<Cred> {
  let j = req.body().to_str().parse_json().ok()?;
  let name = j.get("name").and_then(|v| v.as_str())?;
  let password = j.get("password").and_then(|v| v.as_str())?;
  Some(Cred { name: name, password: password })
}

fn hash(name: Str, password: Str) -> Str {
  ("kio:" + name + ":" + password).sha256().to_hex()
}

fn get_int(store: Kv, key: Str) -> Result<Int, KvErr> {
  match store.get(key)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn token_of(req: Incoming) -> Option<Str> {
  let h = header(req, "authorization")?;
  let t = h.strip_prefix("Bearer ")?;
  if t.len() != 32 { return None; }
  Some(t)
}

fn load_session(store: Kv, token: Str) -> Result<Option<Sess>, KvErr> {
  let Some(b) = store.get("sess:" + token)? else { return Ok(None); };
  let f = b.to_str().split(" ");
  if f.len() != 2 { return Ok(None); }
  let Some(e) = f[1].parse_int() else { return Ok(None); };
  Ok(Some(Sess { name: f[0], expiry: e }))
}

fn create_user(req: Incoming, store: Kv) -> Result<Reply, KvErr> {
  let Some(c) = creds(req) else { return Ok(error(400, "invalid")); };
  if !valid_name(c.name) || c.password.len() < 8 { return Ok(error(400, "invalid")); }
  let made = store.swap("user:" + c.name, None, Some(hash(c.name, c.password).to_bytes()))?;
  if !made { return Ok(error(409, "name taken")); }
  Ok(Reply { status: 201, body: obj1("name", Json::Str(c.name)) })
}

fn login(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Reply, KvErr> {
  let bad = error(401, "bad credentials");
  let Some(c) = creds(req) else { return Ok(bad); };
  if !valid_name(c.name) { return Ok(bad); }
  let stored = match store.get("user:" + c.name)? {
    Some(b) => b.to_str(),
    None => return Ok(bad),
  };
  let now = clock.now_ms();
  let until = get_int(store, "lock:" + c.name)?;
  if now < until { return Ok(error(429, "locked")); }
  if !hash(c.name, c.password).ct_eq(stored) {
    let fails = store.add("fails:" + c.name, 1)?;
    if fails >= 3 {
      store.set("lock:" + c.name, (now + 900000).to_str().to_bytes())?;
      store.delete("fails:" + c.name)?;
    }
    return Ok(bad);
  }
  store.delete("fails:" + c.name)?;
  store.add("logins:" + c.name, 1)?;
  let token = rng.bytes(16).to_hex();
  store.set("sess:" + token, (c.name + " " + (now + 1800000).to_str()).to_bytes())?;
  let mut m: Map<Str, Json> = Map::new();
  m.insert("token", Json::Str(token));
  m.insert("expires_in", Json::Num(1800));
  Ok(Reply { status: 200, body: Json::Obj(m) })
}

fn me(req: Incoming, store: Kv, clock: Clock) -> Result<Reply, KvErr> {
  let un = error(401, "unauthorized");
  let Some(token) = token_of(req) else { return Ok(un); };
  let Some(s) = load_session(store, token)? else { return Ok(un); };
  let now = clock.now_ms();
  if now >= s.expiry { return Ok(un); }
  store.set("sess:" + token, (s.name + " " + (now + 1800000).to_str()).to_bytes())?;
  let n = get_int(store, "logins:" + s.name)?;
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(s.name));
  m.insert("logins", Json::Num(n));
  Ok(Reply { status: 200, body: Json::Obj(m) })
}

fn logout(req: Incoming, store: Kv, clock: Clock) -> Result<Reply, KvErr> {
  let un = error(401, "unauthorized");
  let Some(token) = token_of(req) else { return Ok(un); };
  let Some(s) = load_session(store, token)? else { return Ok(un); };
  if clock.now_ms() >= s.expiry { return Ok(un); }
  store.delete("sess:" + token)?;
  Ok(Reply { status: 204, body: Json::Null })
}

fn route(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Reply, KvErr> {
  let path = req.target().split("?")[0];
  let method = req.method();
  if method == "POST" && path == "/users" { return create_user(req, store); }
  if method == "POST" && path == "/login" { return login(req, store, clock, rng); }
  if method == "GET" && path == "/me" { return me(req, store, clock); }
  if method == "POST" && path == "/logout" { return logout(req, store, clock); }
  Ok(error(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<(), WebErr> {
  let r = route(req, store, clock, rng).unwrap_or(error(500, "store failed"));
  if r.status == 204 {
    return res.send(204, [], [], "".to_bytes());
  }
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes())
}

struct Reply { status: Int, body: Str }

fn text(row: List<SqlValue>, i: Int) -> Str { match row[i] { SqlValue::Text(s) => s, _ => "" } }
fn int(row: List<SqlValue>, i: Int) -> Int { match row[i] { SqlValue::Int(n) => n, _ => 0 } }

fn pay_json(row: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str("pay_" + int(row, 0).to_str()));
  m.insert("account", Json::Str(text(row, 1)));
  m.insert("cents", Json::Num(int(row, 2)));
  m.insert("currency", Json::Str(text(row, 3)));
  m.insert("status", Json::Str(text(row, 4)));
  m.insert("refunded", Json::Num(int(row, 5)));
  Json::Obj(m)
}

fn err(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m).to_json() }
}

fn ok(status: Int, j: Json) -> Reply { Reply { status: status, body: j.to_json() } }

const COLS: Str = "SELECT n, account, cents, currency, status, refunded FROM payments ";

fn load(db: Db, id: Int) -> Result<Option<Json>, DbErr> {
  let rows = db.query(COLS + "WHERE n = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { Ok(None) } else { Ok(Some(pay_json(rows[0]))) }
}

fn pid(s: Str) -> Option<Int> {
  let n = s.strip_prefix("pay_")?;
  let v = n.parse_int()?;
  if v > 0 && v.to_str() == n { Some(v) } else { None }
}

fn status_of(j: Json) -> Str { j.get("status").and_then(|v| v.as_str()).unwrap_or("") }

fn header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() { if names[i] == name { return Some(values[i]); } }
  None
}

fn query_arg(target: Str, key: Str) -> Option<Str> {
  let q = target.split("?");
  if q.len() < 2 { return None; }
  for pair in q[1].split("&") {
    if let Some(v) = pair.strip_prefix(key + "=") { return Some(v); }
  }
  None
}

fn do_create(db: Db, raw: Str) -> Result<Reply, DbErr> {
  let bad = err(422, "invalid payment");
  let Ok(j) = raw.parse_json() else { return Ok(bad); };
  let Some(m) = j.as_map() else { return Ok(bad); };
  if m.len() != 3 { return Ok(bad); }
  let Some(account) = j.get("account").and_then(|v| v.as_str()) else { return Ok(bad); };
  let Some(cents) = j.get("cents").and_then(|v| v.as_int()) else { return Ok(bad); };
  let Some(cur) = j.get("currency").and_then(|v| v.as_str()) else { return Ok(bad); };
  if account == "" || cents <= 0 { return Ok(bad); }
  if cur != "EUR" && cur != "USD" { return Ok(bad); }
  let rows = db.query("INSERT INTO payments (account, cents, currency, status, refunded) VALUES (?, ?, ?, 'pending', 0) RETURNING n",
    [SqlValue::Text(account), SqlValue::Int(cents), SqlValue::Text(cur)])?;
  let id = int(rows[0], 0);
  let Some(p) = load(db, id)? else { return Ok(err(500, "lost")); };
  Ok(ok(201, p))
}

fn do_refund(db: Db, id: Int, raw: Str) -> Result<Reply, DbErr> {
  let bad = err(422, "invalid refund");
  let Ok(j) = raw.parse_json() else { return Ok(bad); };
  let Some(n) = j.get("cents").and_then(|v| v.as_int()) else { return Ok(bad); };
  if n <= 0 { return Ok(bad); }
  let Some(_) = load(db, id)? else { return Ok(err(404, "not found")); };
  let changed = db.exec("UPDATE payments SET refunded = refunded + ?, status = CASE WHEN refunded + ? = cents THEN 'refunded' ELSE status END WHERE n = ? AND status = 'captured' AND refunded + ? <= cents",
    [SqlValue::Int(n), SqlValue::Int(n), SqlValue::Int(id), SqlValue::Int(n)])?;
  let Some(p) = load(db, id)? else { return Ok(err(404, "not found")); };
  if changed > 0 { return Ok(ok(200, p)); }
  if status_of(p) != "captured" { return Ok(err(409, "invalid transition")); }
  Ok(err(409, "exceeds captured"))
}

fn transition(db: Db, id: Int, from: Str, to: Str) -> Result<Reply, DbErr> {
  let changed = db.exec("UPDATE payments SET status = ? WHERE n = ? AND status = ?",
    [SqlValue::Text(to), SqlValue::Int(id), SqlValue::Text(from)])?;
  let Some(p) = load(db, id)? else { return Ok(err(404, "not found")); };
  if changed > 0 { return Ok(ok(200, p)); }
  if from == "pending" && to == "captured" && status_of(p) == "captured" { return Ok(ok(200, p)); }
  Ok(err(409, "invalid transition"))
}

fn idempotent(req: Incoming, db: Db, key: Str, path: Str, id: Int, create: Bool) -> Result<Reply, DbErr> {
  let method = req.method();
  let raw = req.body().to_str();
  let canon = match raw.parse_json() { Ok(j) => j.to_json(), Err(_) => raw };
  let rows = db.query("SELECT method, path, body, status, resp FROM idem WHERE key = ?", [SqlValue::Text(key)])?;
  if rows.len() > 0 {
    let r = rows[0];
    if text(r, 0) == method && text(r, 1) == path && text(r, 2) == canon {
      return Ok(Reply { status: int(r, 3), body: text(r, 4) });
    }
    return Ok(err(409, "key reused"));
  }
  let reply = if create { do_create(db, raw)? } else { do_refund(db, id, raw)? };
  if reply.status >= 200 && reply.status < 300 {
    let _ = db.exec("INSERT OR IGNORE INTO idem (key, method, path, body, status, resp) VALUES (?, ?, ?, ?, ?, ?)",
      [SqlValue::Text(key), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(canon),
       SqlValue::Int(reply.status), SqlValue::Text(reply.body)]);
  }
  Ok(reply)
}

fn route(req: Incoming, db: Db) -> Result<Reply, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (key TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  let target = req.target();
  let path = target.split("?")[0];
  let parts = path.split("/");
  let nf = err(404, "not found");
  let method = req.method();
  if method == "GET" {
    if path == "/payments" {
      let mut rows: List<List<SqlValue>> = [];
      match query_arg(target, "account") {
        Some(a) => { rows = db.query(COLS + "WHERE account = ? ORDER BY n", [SqlValue::Text(a)])?; },
        None => { rows = db.query(COLS + "ORDER BY n", [])?; },
      }
      return Ok(ok(200, Json::Arr(rows.map(|r| pay_json(r)))));
    }
    if parts.len() == 3 && parts[1] == "payments" {
      let Some(id) = pid(parts[2]) else { return Ok(nf); };
      let Some(p) = load(db, id)? else { return Ok(nf); };
      return Ok(ok(200, p));
    }
    return Ok(nf);
  }
  if method != "POST" { return Ok(nf); }
  if path == "/payments" {
    let Some(key) = header(req, "idempotency-key") else { return Ok(err(400, "missing idempotency key")); };
    return idempotent(req, db, key, path, 0, true);
  }
  if parts.len() == 4 && parts[1] == "payments" {
    let act = parts[3];
    if act == "refund" {
      let Some(key) = header(req, "idempotency-key") else { return Ok(err(400, "missing idempotency key")); };
      let Some(id) = pid(parts[2]) else { return Ok(nf); };
      return idempotent(req, db, key, path, id, false);
    }
    let Some(id) = pid(parts[2]) else { return Ok(nf); };
    if act == "capture" { return transition(db, id, "pending", "captured"); }
    if act == "cancel" { return transition(db, id, "pending", "canceled"); }
  }
  Ok(nf)
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<(), WebErr> {
  let r = route(req, db).unwrap_or(err(500, "internal error"));
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())
}

struct Ev { user: Str, page: Str, t: Int }

fn num(b: Bytes, from: Int, to: Int) -> Int {
  let mut n = 0;
  for i in from..to { n = n * 10 + (b[i] - 48); }
  n
}

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }

fn parse_time(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 20 { return None; }
  for i in 0..20 {
    if i == 4 || i == 7 {
      if b[i] != 45 { return None; }
    } else if i == 10 {
      if b[i] != 84 { return None; }
    } else if i == 13 || i == 16 {
      if b[i] != 58 { return None; }
    } else if i == 19 {
      if b[i] != 90 { return None; }
    } else if !is_digit(b[i]) {
      return None;
    }
  }
  let y = num(b, 0, 4);
  let m = num(b, 5, 7);
  let d = num(b, 8, 10);
  let h = num(b, 11, 13);
  let mi = num(b, 14, 16);
  let sec = num(b, 17, 19);
  if m < 1 || m > 12 { return None; }
  if h > 23 || mi > 59 || sec > 59 { return None; }
  let leap = y % 4 == 0 && (y % 100 != 0 || y % 400 == 0);
  let mut dim = 31;
  if m == 4 || m == 6 || m == 9 || m == 11 { dim = 30; }
  if m == 2 { dim = if leap { 29 } else { 28 }; }
  if d < 1 || d > dim { return None; }
  let yy = (y + 400) - (if m <= 2 { 1 } else { 0 });
  let era = yy / 400;
  let yoe = yy - era * 400;
  let mp = (m + 9) % 12;
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  let days = era * 146097 + doe;
  Some(days * 86400 + h * 3600 + mi * 60 + sec)
}

fn parse_line(line: Str) -> Option<Ev> {
  let f = line.split(" ");
  if f.len() != 3 { return None; }
  if f[1] == "" || f[2] == "" { return None; }
  let t = parse_time(f[0])?;
  Some(Ev { user: f[1], page: f[2], t: t })
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn hms(s: Int) -> Str {
  pad2(s / 3600) + ":" + pad2((s % 3600) / 60) + ":" + pad2(s % 60)
}

fn row(user: Str, sessions: Int, events: Int, longest: Int, pages: Int) -> Str {
  user + " sessions " + sessions.to_str() + " events " + events.to_str()
    + " longest " + hms(longest) + " pages " + pages.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut evs: List<Ev> = [];
  let mut seen: Map<Str, Bool> = Map::new();
  let mut malformed = 0;
  let mut dups = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let Some(e) = parse_line(line) else { malformed += 1; continue; };
    if seen.get(line).is_some() { dups += 1; continue; }
    seen.insert(line, true);
    evs.push(e);
  }
  let tail = "malformed " + malformed.to_str() + " duplicates " + dups.to_str();
  if evs.len() == 0 { return Ok(tail); }

  let mut page_counts: Map<Str, Int> = Map::new();
  for e in evs {
    page_counts.insert(e.page, page_counts.get(e.page).unwrap_or(0) + 1);
  }
  evs.sort_by(|a, b| a.user < b.user || (a.user == b.user && a.t < b.t));

  let mut out: List<Str> = [];
  let mut durs: List<Int> = [];
  let mut started = false;
  let mut cur = "";
  let mut sessions = 0;
  let mut events = 0;
  let mut longest = 0;
  let mut pages: Map<Str, Bool> = Map::new();
  let mut start = 0;
  let mut last = 0;
  for e in evs {
    if started && e.user != cur {
      let d = last - start;
      durs.push(d);
      longest = longest.max(d);
      out.push(row(cur, sessions, events, longest, pages.len()));
      started = false;
    }
    if !started {
      cur = e.user;
      sessions = 1;
      events = 1;
      longest = 0;
      pages = Map::new();
      pages.insert(e.page, true);
      start = e.t;
      last = e.t;
      started = true;
    } else {
      events += 1;
      pages.insert(e.page, true);
      if e.t - last > 1800 {
        let d = last - start;
        durs.push(d);
        longest = longest.max(d);
        sessions += 1;
        start = e.t;
      }
      last = e.t;
    }
  }
  if started {
    let d = last - start;
    durs.push(d);
    longest = longest.max(d);
    out.push(row(cur, sessions, events, longest, pages.len()));
  }

  durs.sort();
  out.push("median " + durs[(durs.len() - 1) / 2].to_str());

  let mut names = page_counts.keys();
  names.sort_by(|a, b| {
    let ca = page_counts.get(a).unwrap_or(0);
    let cb = page_counts.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  let top = names.slice(0, names.len().min(3));
  let parts = top.map(|p| p + " (" + page_counts.get(p).unwrap_or(0).to_str() + ")");
  out.push("top: " + parts.join(", "));
  out.push(tail);
  Ok(out.join("\n"))
}

struct Rec { fields: List<Str>, bad: Bool }
struct Row { region: Str, product: Str, qty: Int, cents: Int, line: Str }

fn parse(text: Str) -> List<Rec> {
  let cs = text.chars();
  let n = cs.len();
  let mut recs: List<Rec> = [];
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut fstart = true;
  let mut closed = false;
  let mut bad = false;
  let mut touched = false;
  let mut i = 0;
  while i < n {
    let c = cs[i];
    i += 1;
    if inq {
      if c == "\"" {
        if i < n && cs[i] == "\"" {
          cur += "\"";
          i += 1;
        } else {
          inq = false;
          closed = true;
        }
      } else {
        cur += c;
      }
      continue;
    }
    if c == "\n" || (c == "\r" && i < n && cs[i] == "\n") {
      if c == "\r" { i += 1; }
      if touched {
        fields.push(cur);
        recs.push(Rec { fields: fields, bad: bad });
      }
      fields = [];
      cur = "";
      fstart = true;
      closed = false;
      bad = false;
      touched = false;
      continue;
    }
    touched = true;
    if c == "," {
      fields.push(cur);
      cur = "";
      fstart = true;
      closed = false;
    } else if closed {
      bad = true;
    } else if c == "\"" {
      if fstart {
        inq = true;
        fstart = false;
      } else {
        bad = true;
      }
    } else {
      cur += c;
      fstart = false;
    }
  }
  if touched {
    fields.push(cur);
    recs.push(Rec { fields: fields, bad: bad || inq });
  }
  recs
}

fn digits(s: Str) -> Bool {
  s.len() > 0 && s.chars().all(|c| c >= "0" && c <= "9")
}

fn quote(s: Str) -> Str {
  if s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n") {
    "\"" + s.replace("\"", "\"\"") + "\""
  } else {
    s
  }
}

fn check(rec: Rec) -> Option<Row> {
  if rec.bad { return None; }
  let f = rec.fields;
  if f.len() != 5 { return None; }
  if f[0] == "" || f[1] == "" { return None; }
  let q = f[2];
  let qd = q.strip_prefix("-").unwrap_or(q);
  if !digits(qd) { return None; }
  let qty = q.parse_int()?;
  let pp = f[3].split(".");
  if pp.len() > 2 || !digits(pp[0]) { return None; }
  let mut frac = "00";
  if pp.len() == 2 {
    let d = pp[1];
    if !digits(d) || d.len() > 2 { return None; }
    frac = if d.len() == 1 { d + "0" } else { d };
  }
  let whole = pp[0].parse_int()?;
  let cents = whole * 100 + frac.parse_int()?;
  let price = pp[0] + "." + frac;
  let line = quote(f[0]) + "," + quote(f[1]) + "," + quote(f[2]) + "," + price + "," + quote(f[4]) + "\n";
  Some(Row { region: f[0], product: f[1], qty: qty, cents: cents, line: line })
}

fn money(c: Int) -> Str {
  let a = if c < 0 { -c } else { c };
  let r = a % 100;
  (if c < 0 { "-" } else { "" }) + (a / 100).to_str() + "." + (if r < 10 { "0" } else { "" }) + r.to_str()
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let recs = parse(text);
  let data = if recs.len() > 0 { recs.slice(1, recs.len()) } else { [] };
  let mut clean = "region,product,qty,price,note\n";
  let mut rev: Map<Str, Int> = Map::new();
  let mut items: Map<Str, Int> = Map::new();
  let mut prod: Map<Str, Map<Str, Int>> = Map::new();
  let mut bads: List<Str> = [];
  let mut idx = 0;
  for rec in data {
    idx += 1;
    let Some(r) = check(rec) else {
      bads.push(idx.to_str());
      continue;
    };
    clean += r.line;
    let amt = r.qty * r.cents;
    rev.insert(r.region, rev.get(r.region).unwrap_or(0) + amt);
    items.insert(r.region, items.get(r.region).unwrap_or(0) + r.qty);
    let mut pm: Map<Str, Int> = match prod.get(r.region) {
      Some(m) => m,
      None => Map::new(),
    };
    pm.insert(r.product, pm.get(r.product).unwrap_or(0) + amt);
    prod.insert(r.region, pm);
  }
  out.write("clean.csv", clean.to_bytes())?;
  let mut lines: List<Str> = [];
  for region in rev.keys() {
    let pm: Map<Str, Int> = match prod.get(region) {
      Some(m) => m,
      None => Map::new(),
    };
    let mut best = "";
    let mut best_rev = 0;
    let mut first = true;
    for p in pm.keys() {
      let v = pm.get(p).unwrap_or(0);
      if first || v > best_rev {
        best = p;
        best_rev = v;
        first = false;
      }
    }
    lines.push(region + " revenue " + money(rev.get(region).unwrap_or(0)) + " items " + items.get(region).unwrap_or(0).to_str() + " top " + best);
  }
  let mut last = "records " + data.len().to_str() + " bad " + bads.len().to_str();
  if bads.len() > 0 { last += ": " + bads.join(", "); }
  lines.push(last);
  Ok(lines.join("\n"))
}

struct Ev { path: Str, line: Str }

enum Failed { Io(IoErr), Kv(KvErr) }

fn is_word(x: Int) -> Bool {
  x >= 128 || (x >= 48 && x <= 57) || (x >= 65 && x <= 90) || (x >= 97 && x <= 122)
}

fn words(text: Str) -> List<Str> {
  let mut out: List<Str> = [];
  let mut cur: Bytes = "".to_bytes();
  for x in text.to_bytes() {
    if is_word(x) {
      cur.push(x);
    } else if cur.len() > 0 {
      out.push(cur.to_str().to_lowercase());
      cur = "".to_bytes();
    }
  }
  if cur.len() > 0 { out.push(cur.to_str().to_lowercase()); }
  out
}

fn uniq(ws: List<Str>) -> List<Str> {
  let mut m: Map<Str, Int> = Map::new();
  for w in ws { m.insert(w, 1); }
  m.keys()
}

fn wkey(w: Str) -> Str {
  if w.len() > 400 { "h:" + w.sha256().to_hex() } else { "w:" + w }
}

fn walk(docs: Dir, dir: Str) -> Result<List<Str>, IoErr> {
  let mut out: List<Str> = [];
  let prefix = if dir == "" { "" } else { dir + "/" };
  let names = docs.list(dir)?;
  for n in names {
    if n.ends_with("/") {
      let sub = prefix + n.strip_suffix("/").unwrap_or(n);
      for p in walk(docs, sub)? { out.push(p); }
    } else {
      out.push(prefix + n);
    }
  }
  Ok(out)
}

fn drop_file(index: Kv, path: Str) -> Result<(), KvErr> {
  if let Some(b) = index.get("d:" + path)? {
    for w in b.to_str().split("\n") {
      if w == "" { continue; }
      let k = wkey(w);
      if let Some(pb) = index.get(k)? {
        let rest = pb.to_str().split("\n").filter(|p| p != path && p != "");
        if rest.len() == 0 {
          index.delete(k)?;
        } else {
          index.set(k, rest.join("\n").to_bytes())?;
        }
      }
    }
  }
  index.delete("d:" + path)?;
  index.delete("f:" + path)?;
  Ok(())
}

fn add_file(index: Kv, path: Str, hash: Str, ws: List<Str>) -> Result<(), KvErr> {
  index.set("d:" + path, ws.join("\n").to_bytes())?;
  for w in ws {
    let k = wkey(w);
    let cur = match index.get(k)? {
      Some(b) => b.to_str(),
      None => "",
    };
    let nv = if cur == "" { path } else { cur + "\n" + path };
    index.set(k, nv.to_bytes())?;
  }
  index.set("f:" + path, hash.to_bytes())?;
  Ok(())
}

fn lookup(index: Kv, w: Str) -> Result<List<Str>, KvErr> {
  match index.get(wkey(w))? {
    Some(b) => Ok(b.to_str().split("\n").filter(|p| p != "")),
    None => Ok([]),
  }
}

fn answer(index: Kv, line: Str) -> Result<Str, KvErr> {
  let ws = uniq(words(line));
  if ws.len() == 0 { return Ok(line + ": none"); }
  let mut res: List<Str> = lookup(index, ws[0])?;
  for i in 1..ws.len() {
    let other = lookup(index, ws[i])?;
    res = res.filter(|p| other.contains(p));
  }
  res.sort();
  if res.len() == 0 { Ok(line + ": none") } else { Ok(line + ": " + res.join(", ")) }
}

fn sync(docs: Dir, index: Kv) -> Result<List<Str>, Failed> {
  let mut files = walk(docs, "").map_err(|e| Failed::Io(e))?;
  files.sort();
  let mut cur: Map<Str, Int> = Map::new();
  let mut evs: List<Ev> = [];
  let mut unchanged = 0;
  for path in files {
    cur.insert(path, 1);
    let data = docs.read(path).map_err(|e| Failed::Io(e))?;
    let hash = data.sha256().to_hex();
    let old = index.get("f:" + path).map_err(|e| Failed::Kv(e))?;
    let mut status = "";
    match old {
      None => { status = "added"; }
      Some(h) => {
        if h.to_str() == hash { unchanged += 1; } else { status = "changed"; }
      }
    }
    if status != "" {
      if status == "changed" {
        drop_file(index, path).map_err(|e| Failed::Kv(e))?;
      }
      let ws = uniq(words(data.to_str()));
      add_file(index, path, hash, ws).map_err(|e| Failed::Kv(e))?;
      evs.push(Ev { path: path, line: status + " " + path });
    }
  }
  let stored = index.keys("f:").map_err(|e| Failed::Kv(e))?;
  for k in stored {
    let path = k.strip_prefix("f:").unwrap_or(k);
    if cur.get(path).is_none() {
      drop_file(index, path).map_err(|e| Failed::Kv(e))?;
      evs.push(Ev { path: path, line: "removed " + path });
    }
  }
  evs.sort_by_key(|e| e.path);
  let mut out: List<Str> = evs.map(|e| e.line);
  out.push("unchanged " + unchanged.to_str());
  Ok(out)
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Failed> {
  let mut out = sync(docs, index)?;
  let text = match queries.read("queries.txt") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let a = answer(index, line).map_err(|e| Failed::Kv(e))?;
    out.push(a);
  }
  Ok(out.join("\n"))
}

struct Change { del: Bool, sku: Str, name: Str, qty: Int, version: Int }

fn parse(j: Json) -> Option<Change> {
  let op = j.get("op").and_then(|v| v.as_str())?;
  let sku = j.get("sku").and_then(|v| v.as_str())?;
  let version = j.get("version").and_then(|v| v.as_int())?;
  if op == "delete" {
    return Some(Change { del: true, sku: sku, name: "", qty: 0, version: version });
  }
  if op != "upsert" { return None; }
  let name = j.get("name").and_then(|v| v.as_str())?;
  let qty = j.get("qty").and_then(|v| v.as_int())?;
  Some(Change { del: false, sku: sku, name: name, qty: qty, version: version })
}

fn version_of(db: Db, sku: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT version FROM items WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(n) => Ok(Some(n)),
    _ => Ok(None),
  }
}

fn cell_text(row: List<SqlValue>, i: Int) -> Str {
  match row[i] { SqlValue::Text(s) => s, _ => "" }
}

fn cell_int(row: List<SqlValue>, i: Int) -> Int {
  match row[i] { SqlValue::Int(n) => n, _ => 0 }
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)", [])?;

  let mut cursor = "0";
  let crow = db.query("SELECT value FROM meta WHERE key = 'cursor'", [])?;
  if crow.len() > 0 { cursor = cell_text(crow[0], 0); }

  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status = "complete";

  loop {
    let res = api.send("GET", "/changes?cursor=" + cursor, [], "".to_bytes(), 0);
    let Ok(r) = res else {
      status = "stopped at " + cursor + " (no response)";
      break;
    };
    if r.status != 200 {
      status = "stopped at " + cursor + " (status " + r.status.to_str() + ")";
      break;
    }
    let Ok(doc) = r.body.to_str().parse_json() else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let Some(list) = doc.get("changes").and_then(|v| v.as_list()) else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let nextj = doc.get("next").unwrap_or(Json::Null);
    let mut next: Option<Str> = None;
    let mut bad = false;
    match nextj {
      Json::Null => {},
      Json::Str(s) => { next = Some(s); },
      Json::Num(n) => { next = Some(n.to_str()); },
      _ => { bad = true; },
    }
    if bad {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    }

    let mut cache: Map<Str, Int> = Map::new();
    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut pa = 0;
    let mut ps = 0;
    let mut pi = 0;
    for item in list {
      let Some(c) = parse(item) else { pi += 1; continue; };
      let known = match cache.get(c.sku) {
        Some(v) => Some(v),
        None => version_of(db, c.sku)?,
      };
      let mut is_stale = false;
      if let Some(v) = known {
        if c.version <= v { is_stale = true; }
      }
      if is_stale { ps += 1; continue; }
      pa += 1;
      cache.insert(c.sku, c.version);
      if c.del {
        stmts.push("INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET name = '', qty = 0, version = excluded.version, deleted = 1");
        params.push([SqlValue::Text(c.sku), SqlValue::Int(c.version)]);
      } else {
        stmts.push("INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0");
        params.push([SqlValue::Text(c.sku), SqlValue::Text(c.name), SqlValue::Int(c.qty), SqlValue::Int(c.version)]);
      }
    }
    let newc = next.unwrap_or(cursor);
    stmts.push("INSERT INTO meta(key, value) VALUES('cursor', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value");
    params.push([SqlValue::Text(newc)]);
    db.transaction(stmts, params)?;

    pages += 1;
    applied += pa;
    stale += ps;
    invalid += pi;
    match next {
      Some(n) => cursor = n,
      None => break,
    }
  }

  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  let mut lines: List<Str> = [];
  lines.push("pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str());
  lines.push(status);
  for row in rows {
    lines.push(cell_text(row, 0) + " " + cell_int(row, 1).to_str() + " " + cell_text(row, 2));
  }
  Ok(lines.join("\n"))
}

struct Job { id: Str, priority: Int, due: Int, attempts: Int, status: Str }

fn decode(id: Str, s: Str) -> Option<Job> {
  let f = s.split(",");
  if f.len() != 4 { return None; }
  Some(Job { id: id, priority: f[0].parse_int()?, due: f[1].parse_int()?, attempts: f[2].parse_int()?, status: f[3] })
}

fn encode(j: Job) -> Str {
  j.priority.to_str() + "," + j.due.to_str() + "," + j.attempts.to_str() + "," + j.status
}

fn load(queue: Kv) -> Result<List<Job>, KvErr> {
  let mut jobs: List<Job> = [];
  for k in queue.keys("job:")? {
    let Some(b) = queue.get(k)? else { continue; };
    let id = k.strip_prefix("job:").unwrap_or(k);
    let Some(j) = decode(id, b.to_str()) else { continue; };
    jobs.push(j);
  }
  Ok(jobs)
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, KvErr> {
  let now = clock.now_ms();
  let mut out: List<Str> = [];

  let text = match input.read("enqueue.jsonl") { Ok(b) => b.to_str(), Err(_) => "" };
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    let t = line.trim();
    if t == "" { continue; }
    let Ok(doc) = t.parse_json() else { out.push("invalid line " + n.to_str()); continue; };
    if doc.as_map().is_none() { out.push("invalid line " + n.to_str()); continue; }
    let Some(id) = doc.get("id").and_then(|j| j.as_str()) else { out.push("invalid line " + n.to_str()); continue; };
    let Some(p) = doc.get("priority").and_then(|j| j.as_int()) else { out.push("invalid line " + n.to_str()); continue; };
    let key = "job:" + id;
    match queue.get(key)? {
      Some(_) => out.push("duplicate " + id),
      None => {
        let j = Job { id: id, priority: p, due: now, attempts: 0, status: "p" };
        queue.set(key, encode(j).to_bytes())?;
      },
    }
  }

  let script = match input.read("script.json") {
    Ok(b) => b.to_str().parse_json().unwrap_or(Json::Null),
    Err(_) => Json::Null,
  };

  let all = load(queue)?;
  let mut due = all.filter(|j| j.status == "p" && j.due <= now);
  due.sort_by(|a, b| a.priority > b.priority
    || (a.priority == b.priority && (a.due < b.due || (a.due == b.due && a.id < b.id))));
  let cnt = due.len().min(5);
  for i in 0..cnt {
    let j = due[i];
    let a = j.attempts + 1;
    let outs = script.get(j.id).and_then(|x| x.as_list()).unwrap_or([]);
    let outcome = if outs.len() == 0 { "ok" } else { outs[(a - 1).min(outs.len() - 1)].as_str().unwrap_or("ok") };
    let mut nj = Job { attempts: a, ..j };
    if outcome == "fail" {
      if a >= 4 {
        nj.status = "x";
        out.push("dead " + j.id);
      } else {
        let secs = if a == 1 { 60 } else if a == 2 { 120 } else { 240 };
        nj.due = now + secs * 1000;
        out.push("retry " + j.id + " in " + secs.to_str());
      }
    } else {
      nj.status = "d";
      out.push("done " + j.id);
    }
    queue.set("job:" + j.id, encode(nj).to_bytes())?;
  }

  let fin = load(queue)?;
  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for j in fin {
    if j.status == "p" { p += 1; } else if j.status == "d" { d += 1; } else { x += 1; }
  }
  out.push("pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str());
  Ok(out.join("\n"))
}

const MAX: Int = 9223372036854775807;

struct Tok { kind: Int, text: Str }
struct Node { kind: Int, text: Str, args: List<Node> }
struct PR { node: Node, pos: Int }
struct Stmt { is_let: Bool, name: Str, node: Node }

fn minv() -> Int { -9223372036854775807 - 1 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

fn tokenize(line: Str) -> Option<List<Tok>> {
  let b = line.to_bytes();
  let n = b.len();
  let mut i = 0;
  let mut out: List<Tok> = [];
  while i < n {
    let c = b[i];
    if c == 32 {
      i += 1;
    } else if is_digit(c) {
      let s = i;
      while i < n && is_digit(b[i]) { i += 1; }
      out.push(Tok { kind: 0, text: line.slice(s, i) });
    } else if is_alpha(c) {
      let s = i;
      while i < n && (is_alpha(b[i]) || is_digit(b[i])) { i += 1; }
      out.push(Tok { kind: 1, text: line.slice(s, i) });
    } else if c < 128 && "+-*/%^(),=".contains(line.slice(i, i + 1)) {
      out.push(Tok { kind: 2, text: line.slice(i, i + 1) });
      i += 1;
    } else {
      return None;
    }
  }
  out.push(Tok { kind: 3, text: "" });
  Some(out)
}

fn is_op(t: Tok, s: Str) -> Bool { t.kind == 2 && t.text == s }

fn parse_expr(t: List<Tok>, p: Int) -> Option<PR> {
  let first = parse_term(t, p)?;
  let mut node = first.node;
  let mut pos = first.pos;
  while is_op(t[pos], "+") || is_op(t[pos], "-") {
    let op = t[pos].text;
    let r = parse_term(t, pos + 1)?;
    node = Node { kind: 3, text: op, args: [node, r.node] };
    pos = r.pos;
  }
  Some(PR { node: node, pos: pos })
}

fn parse_term(t: List<Tok>, p: Int) -> Option<PR> {
  let first = parse_factor(t, p)?;
  let mut node = first.node;
  let mut pos = first.pos;
  while is_op(t[pos], "*") || is_op(t[pos], "/") || is_op(t[pos], "%") {
    let op = t[pos].text;
    let r = parse_factor(t, pos + 1)?;
    node = Node { kind: 3, text: op, args: [node, r.node] };
    pos = r.pos;
  }
  Some(PR { node: node, pos: pos })
}

fn parse_factor(t: List<Tok>, p: Int) -> Option<PR> {
  if is_op(t[p], "-") {
    let r = parse_factor(t, p + 1)?;
    return Some(PR { node: Node { kind: 4, text: "", args: [r.node] }, pos: r.pos });
  }
  parse_power(t, p)
}

fn parse_power(t: List<Tok>, p: Int) -> Option<PR> {
  let a = parse_atom(t, p)?;
  if is_op(t[a.pos], "^") {
    let r = parse_factor(t, a.pos + 1)?;
    return Some(PR { node: Node { kind: 3, text: "^", args: [a.node, r.node] }, pos: r.pos });
  }
  Some(a)
}

fn parse_atom(t: List<Tok>, p: Int) -> Option<PR> {
  let tk = t[p];
  if tk.kind == 0 {
    return Some(PR { node: Node { kind: 0, text: tk.text, args: [] }, pos: p + 1 });
  }
  if tk.kind == 1 {
    if is_op(t[p + 1], "(") {
      let mut args: List<Node> = [];
      let r = parse_expr(t, p + 2)?;
      args.push(r.node);
      let mut pos = r.pos;
      while is_op(t[pos], ",") {
        let r2 = parse_expr(t, pos + 1)?;
        args.push(r2.node);
        pos = r2.pos;
      }
      if !is_op(t[pos], ")") { return None; }
      return Some(PR { node: Node { kind: 2, text: tk.text, args: args }, pos: pos + 1 });
    }
    return Some(PR { node: Node { kind: 1, text: tk.text, args: [] }, pos: p + 1 });
  }
  if is_op(tk, "(") {
    let r = parse_expr(t, p + 1)?;
    if !is_op(t[r.pos], ")") { return None; }
    return Some(PR { node: r.node, pos: r.pos + 1 });
  }
  None
}

fn parse_line(t: List<Tok>) -> Option<Stmt> {
  let empty = Node { kind: 0, text: "0", args: [] };
  if t[0].kind == 1 && t[0].text == "let" {
    if t.len() < 3 { return None; }
    if t[1].kind != 1 { return None; }
    if !is_op(t[2], "=") { return None; }
    let r = parse_expr(t, 3)?;
    if t[r.pos].kind != 3 { return None; }
    return Some(Stmt { is_let: true, name: t[1].text, node: r.node });
  }
  let r = parse_expr(t, 0)?;
  if t[r.pos].kind != 3 { return None; }
  Some(Stmt { is_let: false, name: "", node: r.node })
}

fn add(a: Int, b: Int) -> Option<Int> {
  if b > 0 && a > MAX - b { return None; }
  if b < 0 && a < minv() - b { return None; }
  Some(a + b)
}

fn sub(a: Int, b: Int) -> Option<Int> {
  if b > 0 && a < minv() + b { return None; }
  if b < 0 && a > MAX + b { return None; }
  Some(a - b)
}

fn mul(a: Int, b: Int) -> Option<Int> {
  if a == 0 || b == 0 { return Some(0); }
  if a == -1 {
    if b == minv() { return None; }
    return Some(-b);
  }
  if b == -1 {
    if a == minv() { return None; }
    return Some(-a);
  }
  if a > 0 {
    if b > 0 {
      if b > MAX / a { return None; }
    } else {
      if b < minv() / a { return None; }
    }
  } else {
    if b > 0 {
      if b > minv() / a { return None; }
    } else {
      if b < MAX / a { return None; }
    }
  }
  Some(a * b)
}

fn pow(a: Int, b: Int) -> Option<Int> {
  if b == 0 { return Some(1); }
  if a == 0 { return Some(0); }
  if a == 1 { return Some(1); }
  if a == -1 {
    if b % 2 == 0 { return Some(1); }
    return Some(-1);
  }
  if b > 63 { return None; }
  let mut r = 1;
  for _i in 0..b {
    r = mul(r, a)?;
  }
  Some(r)
}

fn binop(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  if op == "+" { return add(a, b).ok_or("overflow"); }
  if op == "-" { return sub(a, b).ok_or("overflow"); }
  if op == "*" { return mul(a, b).ok_or("overflow"); }
  if op == "/" {
    if b == 0 { return Err("division by zero"); }
    if a == minv() && b == -1 { return Err("overflow"); }
    return Ok(a / b);
  }
  if op == "%" {
    if b == 0 { return Err("division by zero"); }
    if b == -1 { return Ok(0); }
    return Ok(a % b);
  }
  if b < 0 { return Err("negative exponent"); }
  pow(a, b).ok_or("overflow")
}

fn eval(n: Node, env: Map<Str, Int>) -> Result<Int, Str> {
  if n.kind == 0 {
    return n.text.parse_int().ok_or("overflow");
  }
  if n.kind == 1 {
    return env.get(n.text).ok_or("unknown variable " + n.text);
  }
  if n.kind == 4 {
    let a = eval(n.args[0], env)?;
    if a == minv() { return Err("overflow"); }
    return Ok(-a);
  }
  if n.kind == 3 {
    let a = eval(n.args[0], env)?;
    let b = eval(n.args[1], env)?;
    return binop(n.text, a, b);
  }
  let name = n.text;
  if name != "min" && name != "max" && name != "abs" {
    return Err("unknown function " + name);
  }
  let want = if name == "abs" { 1 } else { 2 };
  if n.args.len() != want {
    return Err("wrong number of arguments to " + name);
  }
  let mut vals: List<Int> = [];
  for a in n.args {
    let v = eval(a, env)?;
    vals.push(v);
  }
  if name == "min" { return Ok(vals[0].min(vals[1])); }
  if name == "max" { return Ok(vals[0].max(vals[1])); }
  let x = vals[0];
  if x == minv() { return Err("overflow"); }
  if x < 0 { return Ok(-x); }
  Ok(x)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let lines = text.lines();
  let mut env: Map<Str, Int> = Map::new();
  let mut out: List<Str> = [];
  for i in 0..lines.len() {
    let pre = (i + 1).to_str() + ": ";
    let Some(t) = tokenize(lines[i]) else {
      out.push(pre + "error: syntax error");
      continue;
    };
    if t.len() == 1 { continue; }
    let Some(s) = parse_line(t) else {
      out.push(pre + "error: syntax error");
      continue;
    };
    match eval(s.node, env) {
      Ok(v) => {
        if s.is_let {
          env.insert(s.name, v);
          out.push(pre + s.name + " = " + v.to_str());
        } else {
          out.push(pre + v.to_str());
        }
      },
      Err(e) => out.push(pre + "error: " + e),
    }
  }
  Ok(out.join("\n"))
}

struct Out { status: Int, body: Json, logs: List<Str>, retry: Bool }
struct Ev { id: Str, kind: Str, sub: Str, seq: Int }

enum Tx { Done, Dup, Retry }

fn text(row: List<SqlValue>, i: Int) -> Str { match row[i] { SqlValue::Text(s) => s, _ => "" } }
fn int(row: List<SqlValue>, i: Int) -> Int { match row[i] { SqlValue::Int(n) => n, _ => 0 } }

fn obj_str(k: Str, v: Str) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, Json::Str(v));
  Json::Obj(m)
}

fn error(status: Int, msg: Str) -> Out {
  Out { status: status, body: obj_str("error", msg), logs: [], retry: false }
}

fn st(status: Int, s: Str) -> Out {
  Out { status: status, body: obj_str("status", s), logs: [], retry: false }
}

fn header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() { if names[i] == name { return Some(values[i]); } }
  None
}

fn trans(state: Str, t: Str) -> Option<Str> {
  match t {
    "subscription.created" => if state == "none" { Some("created") } else { None },
    "subscription.activated" => if state == "created" || state == "past_due" { Some("active") } else { None },
    "payment.failed" => if state == "active" { Some("past_due") } else { None },
    _ => if state != "none" && state != "canceled" { Some("canceled") } else { None },
  }
}

fn tx(db: Db, sql: List<Str>, ps: List<List<SqlValue>>) -> Result<Tx, DbErr> {
  match db.transaction(sql, ps) {
    Ok(_) => Ok(Tx::Done),
    Err(DbErr::Constraint(m)) => if m.contains("events.id") { Ok(Tx::Dup) } else { Ok(Tx::Retry) },
    Err(e) => Err(e),
  }
}

fn init(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, subscription TEXT NOT NULL, seq INTEGER NOT NULL, type TEXT NOT NULL, applied INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL, history TEXT NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS guard (ok INTEGER CHECK (ok = 1))", [])?;
  Ok(())
}

fn insp(ev: Ev, applied: Int) -> List<SqlValue> {
  [SqlValue::Text(ev.id), SqlValue::Text(ev.sub), SqlValue::Int(ev.seq), SqlValue::Text(ev.kind), SqlValue::Int(applied)]
}

fn attempt(db: Db, ev: Ev) -> Result<Out, DbErr> {
  let dup = db.query("SELECT 1 FROM events WHERE id = ?", [SqlValue::Text(ev.id)])?;
  if dup.len() > 0 { return Ok(st(200, "duplicate")); }
  let rows = db.query("SELECT state, seq, history FROM subs WHERE id = ?", [SqlValue::Text(ev.sub)])?;
  let mut state = "none";
  let mut last = 0;
  let mut hist = "";
  if rows.len() > 0 {
    state = text(rows[0], 0);
    last = int(rows[0], 1);
    hist = text(rows[0], 2);
  }
  let ins = "INSERT INTO events (id, subscription, seq, type, applied) VALUES (?, ?, ?, ?, ?)";
  let guard1 = "INSERT INTO guard (ok) SELECT 0 WHERE (SELECT COALESCE(MAX(seq), 0) FROM subs WHERE id = ?) != ?";
  let guard2 = "INSERT INTO guard (ok) SELECT 0 WHERE (SELECT COALESCE(MAX(seq), 0) FROM subs WHERE id = ?) != ? OR (SELECT COUNT(*) FROM events WHERE subscription = ? AND applied = 0) != ?";
  if ev.seq <= last {
    let r = tx(db, [ins], [insp(ev, 2)])?;
    return Ok(match r {
      Tx::Done => st(200, "stale"),
      Tx::Dup => st(200, "duplicate"),
      Tx::Retry => Out { status: 0, body: Json::Null, logs: [], retry: true },
    });
  }
  if ev.seq > last + 1 {
    let r = tx(db, [ins, guard1], [insp(ev, 0), [SqlValue::Text(ev.sub), SqlValue::Int(last)]])?;
    return Ok(match r {
      Tx::Done => st(202, "queued"),
      Tx::Dup => st(200, "duplicate"),
      Tx::Retry => Out { status: 0, body: Json::Null, logs: [], retry: true },
    });
  }
  let pending = db.query("SELECT id, seq, type FROM events WHERE subscription = ? AND applied = 0 ORDER BY seq, id", [SqlValue::Text(ev.sub)])?;
  let mut stmts: List<Str> = [ins, guard2];
  let mut params: List<List<SqlValue>> = [
    insp(ev, 1),
    [SqlValue::Text(ev.sub), SqlValue::Int(last), SqlValue::Text(ev.sub), SqlValue::Int(pending.len())]
  ];
  let mut history: List<Str> = [];
  if hist != "" { history = hist.split(","); }
  let mut logs: List<Str> = [];
  let mut cur = ev.seq;
  let mut count = 1;
  match trans(state, ev.kind) {
    Some(n) => { state = n; history.push(n); },
    None => logs.push("invalid transition " + ev.id),
  }
  for p in pending {
    if int(p, 1) == cur + 1 {
      let pid = text(p, 0);
      match trans(state, text(p, 2)) {
        Some(n) => { state = n; history.push(n); },
        None => logs.push("invalid transition " + pid),
      }
      stmts.push("UPDATE events SET applied = 1 WHERE id = ?");
      params.push([SqlValue::Text(pid)]);
      cur += 1;
      count += 1;
    }
  }
  stmts.push("UPDATE events SET applied = 2 WHERE subscription = ? AND applied = 0 AND seq <= ?");
  params.push([SqlValue::Text(ev.sub), SqlValue::Int(cur)]);
  stmts.push("INSERT INTO subs (id, state, seq, history) VALUES (?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq, history = excluded.history");
  params.push([SqlValue::Text(ev.sub), SqlValue::Text(state), SqlValue::Int(cur), SqlValue::Text(history.join(","))]);
  let r = tx(db, stmts, params)?;
  Ok(match r {
    Tx::Done => {
      let mut m: Map<Str, Json> = Map::new();
      m.insert("status", Json::Str("applied"));
      m.insert("applied", Json::Num(count));
      Out { status: 200, body: Json::Obj(m), logs: logs, retry: false }
    },
    Tx::Dup => st(200, "duplicate"),
    Tx::Retry => Out { status: 0, body: Json::Null, logs: [], retry: true },
  })
}

fn process(db: Db, ev: Ev) -> Result<Out, DbErr> {
  for i in 0..8 {
    let o = attempt(db, ev)?;
    if !o.retry { return Ok(o); }
  }
  Ok(error(503, "busy"))
}

fn webhook(req: Incoming, db: Db, secrets: Dir, log: Log) -> Out {
  let Ok(kb0) = secrets.read("webhook.key") else { return error(500, "no key"); };
  let mut kb = kb0;
  loop {
    let n = kb.len();
    if n > 0 && (kb[n - 1] == 10 || kb[n - 1] == 13) {
      kb = kb.slice(0, n - 1);
    } else {
      break;
    }
  }
  let body = req.body();
  let mut m = kb;
  m.push(46);
  m.extend(body);
  let expected = m.sha256().to_hex();
  let ok = match header(req, "x-signature") {
    Some(s) => match s.strip_prefix("sha256=") {
      Some(h) => expected.ct_eq(h),
      None => false,
    },
    None => false,
  };
  if !ok {
    if log.write("rejected signature").is_err() { }
    return error(401, "bad signature");
  }
  let Ok(doc) = body.to_str().parse_json() else { return error(400, "invalid event"); };
  if doc.as_map().is_none() { return error(400, "invalid event"); }
  let Some(id) = doc.get("id").and_then(|j| j.as_str()) else { return error(400, "invalid event"); };
  let Some(kind) = doc.get("type").and_then(|j| j.as_str()) else { return error(400, "invalid event"); };
  let Some(sub) = doc.get("subscription").and_then(|j| j.as_str()) else { return error(400, "invalid event"); };
  let Some(seq) = doc.get("seq").and_then(|j| j.as_int()) else { return error(400, "invalid event"); };
  if seq < 1 { return error(400, "invalid event"); }
  if kind != "subscription.created" && kind != "subscription.activated" && kind != "payment.failed" && kind != "subscription.canceled" {
    return error(400, "invalid event");
  }
  let ev = Ev { id: id, kind: kind, sub: sub, seq: seq };
  match process(db, ev) {
    Ok(o) => {
      for l in o.logs { if log.write(l).is_err() { } }
      o
    },
    Err(e) => error(500, "db error"),
  }
}

fn get_sub(db: Db, id: Str) -> Out {
  let Ok(rows) = db.query("SELECT state, seq, history FROM subs WHERE id = ?", [SqlValue::Text(id)]) else {
    return error(500, "db error");
  };
  if rows.len() == 0 { return error(404, "not found"); }
  let row = rows[0];
  let h = text(row, 2);
  let mut hist: List<Json> = [];
  if h != "" { hist = h.split(",").map(|s| Json::Str(s)); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str(id));
  m.insert("state", Json::Str(text(row, 0)));
  m.insert("seq", Json::Num(int(row, 1)));
  m.insert("history", Json::Arr(hist));
  Out { status: 200, body: Json::Obj(m), logs: [], retry: false }
}

fn handle(req: Incoming, db: Db, secrets: Dir, log: Log) -> Out {
  if init(db).is_err() { return error(500, "db error"); }
  let path = req.target().split("?")[0];
  let method = req.method();
  if method == "POST" && path == "/webhooks" {
    return webhook(req, db, secrets, log);
  }
  if method == "GET" {
    if let Some(id) = path.strip_prefix("/subscriptions/") {
      if id != "" && !id.contains("/") { return get_sub(db, id); }
    }
  }
  error(404, "not found")
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<(), WebErr> {
  let o = handle(req, db, secrets, log);
  res.send(o.status, ["content-type"], ["application/json"], o.body.to_json().to_bytes())
}
